"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["6607"],{7735(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"ai-coding","metadata":{"permalink":"/blog/ai-coding","source":"@site/blog/2026-05-06-ai-coding.md","title":"ai coding \u8B93\u6211\u958B\u59CB\u5BB3\u6015\u81EA\u5DF1\u5FD8\u8A18\u600E\u9EBC\u601D\u8003","description":"\u6700\u8FD1\u6211\u6709\u500B\u7FD2\u6163\u8B93\u6211\u6709\u9EDE\u4E0D\u5B89\u2014\u2014\u6211\u767C\u73FE\u6211\u5728\u7528 AI \u5BEB\u7A0B\u5F0F\u7684\u6642\u5019\uFF0C\u6839\u672C\u4E0D\u6703\u5148\u60F3\u300C\u9019\u8981\u600E\u9EBC\u505A\u300D\uFF0C\u800C\u662F\u76F4\u63A5\u6253\u958B\u5C0D\u8A71\u6846\uFF0C\u628A\u9700\u6C42\u8CBC\u9032\u53BB\uFF0C\u7B49\u7D50\u679C\u51FA\u4F86\u3002","date":"2026-05-06T00:06:32.090Z","tags":[{"inline":true,"label":"ai","permalink":"/blog/tags/ai"}],"readingTime":3.55,"hasTruncateMarker":false,"authors":[{"name":"Liwen","title":"Digital Architect / Full Stack Developer","url":"https://github.com/liwenchiou","imageURL":"https://github.com/liwenchiou.png","key":"liwen","page":null}],"frontMatter":{"slug":"ai-coding","title":"ai coding \u8B93\u6211\u958B\u59CB\u5BB3\u6015\u81EA\u5DF1\u5FD8\u8A18\u600E\u9EBC\u601D\u8003","date":"2026-05-06T00:06:32.090Z","authors":["liwen"],"tags":["ai"]},"unlisted":false,"nextItem":{"title":"\u5C0F\u5915\u51FA\u6708\u4E2D\u8A18","permalink":"/blog/weekend-dad-full-time-heart"}},"content":"\u6700\u8FD1\u6211\u6709\u500B\u7FD2\u6163\u8B93\u6211\u6709\u9EDE\u4E0D\u5B89\u2014\u2014\u6211\u767C\u73FE\u6211\u5728\u7528 AI \u5BEB\u7A0B\u5F0F\u7684\u6642\u5019\uFF0C\u6839\u672C\u4E0D\u6703\u5148\u60F3\u300C\u9019\u8981\u600E\u9EBC\u505A\u300D\uFF0C\u800C\u662F\u76F4\u63A5\u6253\u958B\u5C0D\u8A71\u6846\uFF0C\u628A\u9700\u6C42\u8CBC\u9032\u53BB\uFF0C\u7B49\u7D50\u679C\u51FA\u4F86\u3002\\n\\n\u6709\u4E00\u5929\u6211\u7A81\u7136\u610F\u8B58\u5230\uFF1A\u5982\u679C AI \u4ECA\u5929\u6D88\u5931\u4E86\uFF0C\u6211\u9084\u6703\u5BEB\u7A0B\u5F0F\u55CE\uFF1F\\n\\n\\n`{`/* truncate */`}`\\n\\n\\n---\\n\\n## \u4E00\u500B\u8B93\u6211\u9A5A\u9192\u7684\u5C0F\u9700\u6C42\\n\\n\u4E8B\u60C5\u662F\u9019\u6A23\u7684\u3002\u6211\u5728\u505A\u4E00\u500B\u529F\u80FD\uFF0C\u6709\u500B\u6B04\u4F4D\u88E1\u9762\u5B58\u4E86\u591A\u5BB6\u516C\u53F8\u7684 tag\uFF0C\u7522\u54C1\u9700\u6C42\u662F\uFF1A**\u8D85\u904E 3 \u5BB6\u516C\u53F8\u7684\u6642\u5019\uFF0C\u4E0D\u8981\u5168\u90E8\u5217\u51FA\u4F86\uFF0C\u6539\u6210\u986F\u793A\u4E00\u500B\u300COpen Model\u300D\u7684 tag\uFF0C\u4F7F\u7528\u8005\u9EDE\u64CA\u4E4B\u5F8C\u8DF3\u51FA\u5F48\u8DF3\u8996\u7A97\u770B\u660E\u7D30\u3002**\\n\\n\u4EE5\u524D\u7684\u6211\uFF0C\u6703\u76F4\u63A5\u9019\u6A23\u8DDF AI \u8AAA\uFF1A\\n\\n> \u300C\u9019\u6B04\u4F4D\u88E1\u9762\u6293\u51FA\u4F86\u7684\u516C\u53F8\uFF0C\u5982\u679C\u8D85\u904E 3 \u5BB6\u76F4\u63A5\u5E6B\u6211\u986F\u793A open model \u7684 tag\uFF0C\u9EDE\u958B\u4E4B\u5F8C\u6211\u8981\u53EF\u4EE5\u770B\u5230\u660E\u7D30\u300D\\n\\n\u9019\u6A23\u8AAA\u6C92\u6709\u932F\uFF0C\u529F\u80FD\u4E5F\u6703\u52D5\u3002\\n\\n\u4F46\u6211\u767C\u73FE\u4E00\u4EF6\u4E8B\uFF1A**\u6211\u5B8C\u5168\u4E0D\u77E5\u9053 AI \u600E\u9EBC\u505A\u5230\u7684\u3002**\\n\\n\u6211\u4E0D\u77E5\u9053\u5B83\u7528\u4EC0\u9EBC\u8CC7\u6599\u7D50\u69CB\u5B58\u516C\u53F8\u6E05\u55AE\uFF0C\u4E0D\u77E5\u9053\u5B83\u600E\u9EBC\u5224\u65B7\u6578\u91CF\uFF0C\u4E0D\u77E5\u9053 modal \u662F\u600E\u9EBC\u89F8\u767C\u7684\u3002\u5982\u679C\u5B83\u751F\u51FA\u4F86\u7684\u6771\u897F\u6709 bug\uFF0C\u6211\u751A\u81F3\u4E0D\u77E5\u9053\u8981\u5F9E\u54EA\u88E1\u4E0B\u624B\u3002\\n\\n---\\n\\n## \u6211\u6C7A\u5B9A\u6539\u8B8A\u554F\u6CD5\\n\\n\u5F8C\u4F86\u6211\u5F37\u8FEB\u81EA\u5DF1\u5148\u60F3\u4E00\u904D\u6D41\u7A0B\uFF0C\u518D\u8DDF AI \u8AAA\uFF1A\\n\\n> \u300C\u9019\u500B\u6B04\u4F4D\u6293\u51FA\u4F86\u7684\u516C\u53F8\u6E05\u55AE\uFF0C\u5E6B\u6211\u7528\u9663\u5217\u8B8A\u6578\u5148\u5132\u5B58\u8D77\u4F86\u3002\u5982\u679C\u516C\u53F8\u6578\u91CF\u8D85\u904E 3 \u5BB6\uFF0C\u986F\u793A Open Model \u7684 tag\uFF0C\u4F7F\u7528\u8005\u9EDE\u64CA\u4E4B\u5F8C\u8DF3\u51FA\u5F48\u8DF3\u8996\u7A97\uFF0C\u88E1\u9762\u5217\u51FA\u5B8C\u6574\u7684\u516C\u53F8\u660E\u7D30\u3002\u300D\\n\\n\u5DEE\u5728\u54EA\u88E1\uFF1F\\n\\n\u6211\u5728\u8AAA\u9019\u53E5\u8A71\u4E4B\u524D\uFF0C\u8166\u888B\u88E1\u5DF2\u7D93\u8DD1\u904E\u4E00\u904D\uFF1A\\n- \u5148\u7528**\u9663\u5217**\u628A\u8CC7\u6599\u5B58\u8D77\u4F86\\n- **\u5224\u65B7\u9663\u5217\u9577\u5EA6**\u662F\u5426\u8D85\u904E 3\\n- \u8D85\u904E\u7684\u8A71**\u6E32\u67D3 tag**\\n- \u9EDE\u64CA\u89F8\u767C**modal \u986F\u793A\u660E\u7D30**\\n\\nAI \u53EA\u662F\u5E6B\u6211\u628A\u9019\u500B\u908F\u8F2F\u5BEB\u6210\u7A0B\u5F0F\u78BC\uFF0C**\u908F\u8F2F\u662F\u6211\u7684**\u3002\\n\\n---\\n\\n## \u7528\u7A0B\u5F0F\u78BC\u4F86\u8AAA\u660E\u5DEE\u7570\\n\\n\u8B93\u6211\u7528\u5BE6\u969B\u7684\u4F8B\u5B50\u8B93\u9019\u500B\u5DEE\u7570\u66F4\u5177\u9AD4\u3002\\n\\n### \u300C\u7D50\u679C\u5C0E\u5411\u300D\u7684\u554F\u6CD5\uFF0CAI \u53EF\u80FD\u751F\u51FA\u9019\u7A2E\u6771\u897F\uFF1A\\n\\n```jsx\\nfunction CompanyTags({ companies }) {\\n  if (companies.length > 3) {\\n    return <span className=\\"tag\\">Open Model</span>;\\n  }\\n  return companies.map(c => <span className=\\"tag\\">{c}</span>);\\n}\\n```\\n\\n\u529F\u80FD\u662F\u6709\u4E86\uFF0C\u4F46\u4F60\u770B\u5230\u9019\u6BB5 code \u53EF\u80FD\u9084\u662F\u9727\u715E\u715E\u2014\u2014modal \u5462\uFF1F\u660E\u7D30\u5462\uFF1F\u4F60\u53EF\u80FD\u8981\u518D\u554F\u4E00\u6B21\uFF0C\u7136\u5F8C AI \u5E6B\u4F60\u52A0\u4E0A\u53BB\uFF0C\u7D50\u679C\u6574\u500B\u908F\u8F2F\u6563\u5728\u5404\u5730\uFF0C\u4F60\u4E5F\u4E0D\u77E5\u9053\u70BA\u4EC0\u9EBC\u3002\\n\\n### \u300C\u908F\u8F2F\u5C0E\u5411\u300D\u7684\u554F\u6CD5\uFF0C\u4F60\u8166\u888B\u88E1\u6709\u67B6\u69CB\uFF0CAI \u751F\u51FA\u4F86\u7684\u6771\u897F\u624D\u662F\u5B8C\u6574\u7684\uFF1A\\n\\n```jsx\\nimport { useState } from \\"react\\";\\n\\nfunction CompanyTags({ companies }) {\\n  const [isOpen, setIsOpen] = useState(false);\\n\\n  // 1. \u7528\u9663\u5217\u8B8A\u6578\u5132\u5B58\u516C\u53F8\u6E05\u55AE\uFF08companies \u672C\u8EAB\u5C31\u662F\u9663\u5217\uFF09\\n  // 2. \u5224\u65B7\u6578\u91CF\u662F\u5426\u8D85\u904E 3 \u5BB6\\n  const isOverLimit = companies.length > 3;\\n\\n  return (\\n    <>\\n      {isOverLimit ? (\\n        // 3. \u8D85\u904E\u5C31\u986F\u793A Open Model tag\\n        <span\\n          className=\\"tag open-model\\"\\n          onClick={() => setIsOpen(true)}\\n          style={{ cursor: \\"pointer\\" }}\\n        >\\n          Open Model\\n        </span>\\n      ) : (\\n        // \u6C92\u8D85\u904E\u5C31\u6B63\u5E38\u5217\u51FA\\n        companies.map((company, i) => (\\n          <span key={i} className=\\"tag\\">{company}</span>\\n        ))\\n      )}\\n\\n      {/* 4. Modal\uFF1A\u986F\u793A\u516C\u53F8\u660E\u7D30 */}\\n      {isOpen && (\\n        <div className=\\"modal-overlay\\" onClick={() => setIsOpen(false)}>\\n          <div className=\\"modal-box\\" onClick={e => e.stopPropagation()}>\\n            <h3>\u516C\u53F8\u6E05\u55AE</h3>\\n            <ul>\\n              {companies.map((company, i) => (\\n                <li key={i}>{company}</li>\\n              ))}\\n            </ul>\\n            <button onClick={() => setIsOpen(false)}>\u95DC\u9589</button>\\n          </div>\\n        </div>\\n      )}\\n    </>\\n  );\\n}\\n```\\n\\n\u9019\u7248\u4F60\u770B\u5F97\u61C2\uFF1A\u9663\u5217\u5728\u54EA\u3001\u5224\u65B7\u5728\u54EA\u3001modal \u600E\u9EBC\u958B\u3001\u600E\u9EBC\u95DC\u3002\u54EA\u88E1\u51FA\u554F\u984C\uFF0C\u4F60\u77E5\u9053\u8981\u53BB\u627E\u54EA\u88E1\u3002\\n\\n---\\n\\n## \u5169\u7A2E\u554F\u6CD5\u7684\u672C\u8CEA\u5DEE\u7570\\n\\n| | \u7D50\u679C\u5C0E\u5411 | \u908F\u8F2F\u5C0E\u5411 |\\n|---|---|---|\\n| \u4F60\u5728\u505A\u4EC0\u9EBC | \u63CF\u8FF0\u4F60\u8981\u4EC0\u9EBC | \u63CF\u8FF0\u600E\u9EBC\u505A\u5230 |\\n| AI \u7684\u89D2\u8272 | \u5E6B\u4F60\u89E3\u6C7A\u554F\u984C | \u5E6B\u4F60\u628A\u60F3\u6CD5\u5BEB\u6210 code |\\n| \u51FA bug \u6642 | \u4E0D\u77E5\u5F9E\u4F55\u4E0B\u624B | \u77E5\u9053\u8981\u53BB\u54EA\u88E1\u627E |\\n| \u9577\u671F\u5F71\u97FF | \u908F\u8F2F\u80FD\u529B\u9000\u5316 | \u6301\u7E8C\u5728\u7DF4\u7FD2\u62C6\u89E3\u554F\u984C |\\n\\n---\\n\\n## \u5176\u5BE6\u9019\u4E0D\u662F AI \u7684\u554F\u984C\\n\\n\u4ED4\u7D30\u60F3\u60F3\uFF0C\u9019\u500B\u554F\u984C\u4E0D\u662F AI \u9020\u6210\u7684\uFF0C\u800C\u662F**\u6211\u8B93\u81EA\u5DF1\u8DF3\u904E\u4E86\u601D\u8003\u7684\u6B65\u9A5F**\u3002\\n\\n\u4EE5\u524D\u6C92\u6709 AI \u7684\u6642\u5019\uFF0C\u6211\u8981\u81EA\u5DF1 Google\u3001\u81EA\u5DF1\u62FC\u6E4A\u3001\u81EA\u5DF1\u60F3\u67B6\u69CB\u2014\u2014\u90A3\u500B\u904E\u7A0B\u96D6\u7136\u75DB\u82E6\uFF0C\u4F46\u6B63\u662F\u90A3\u500B\u904E\u7A0B\u5728\u935B\u934A\u908F\u8F2F\u3002\\n\\nAI \u7684\u51FA\u73FE\uFF0C\u8B93\u9019\u500B\u904E\u7A0B\u53EF\u4EE5\u8DF3\u904E\u3002\u4F46\u8DF3\u904E\u4E0D\u4EE3\u8868\u4E0D\u9700\u8981\u3002\\n\\n\u6240\u4EE5\u6211\u73FE\u5728\u7D66\u81EA\u5DF1\u5B9A\u4E86\u4E00\u500B\u898F\u5247\uFF1A\\n\\n> **\u5728\u6253\u958B AI \u4E4B\u524D\uFF0C\u5148\u5728\u8166\u888B\u88E1\u6216\u7D19\u4E0A\u628A\u6B65\u9A5F\u62C6\u4E00\u904D\u3002**\\n\\n\u4E0D\u9700\u8981\u60F3\u5230 code \u5C64\u7D1A\uFF0C\u4F46\u81F3\u5C11\u8981\u60F3\u5230\uFF1A\u8CC7\u6599\u600E\u9EBC\u5B58\u3001\u5224\u65B7\u689D\u4EF6\u662F\u4EC0\u9EBC\u3001\u89F8\u767C\u4EC0\u9EBC\u4E8B\u4EF6\u3001\u5448\u73FE\u4EC0\u9EBC\u7D50\u679C\u3002\\n\\n\u9019\u6A23 AI \u5C31\u56DE\u5230\u5B83\u8A72\u6709\u7684\u4F4D\u7F6E\u2014\u2014**\u662F\u5DE5\u5177\uFF0C\u4E0D\u662F\u5927\u8166\u3002**\\n\\n---"},{"id":"weekend-dad-full-time-heart","metadata":{"permalink":"/blog/weekend-dad-full-time-heart","source":"@site/blog/2026-05-03-weekend-dad-full-time-heart.md","title":"\u5C0F\u5915\u51FA\u6708\u4E2D\u8A18","description":"\u5C0F\u5915\u7D42\u65BC\u51FA\u6708\u4E2D\u4E86\uFF01\u56DE\u9867\u9019\u4E00\u500B\u6708\uFF0C\u65E5\u5B50\u904E\u5F97\u65E2\u75B2\u618A\u53C8\u5145\u5BE6\uFF0C\u9084\u5145\u6EFF\u4E86\u5404\u7A2E\u300C\u9A5A\u559C\u300D\u3002","date":"2026-05-03T11:37:41.837Z","tags":[{"inline":true,"label":"\u80B2\u5152","permalink":"/blog/tags/\u80B2\u5152"}],"readingTime":2.55,"hasTruncateMarker":false,"authors":[{"name":"Liwen","title":"Digital Architect / Full Stack Developer","url":"https://github.com/liwenchiou","imageURL":"https://github.com/liwenchiou.png","key":"liwen","page":null}],"frontMatter":{"slug":"weekend-dad-full-time-heart","title":"\u5C0F\u5915\u51FA\u6708\u4E2D\u8A18","date":"2026-05-03T11:37:41.837Z","authors":["liwen"],"tags":["\u80B2\u5152"]},"unlisted":false,"prevItem":{"title":"ai coding \u8B93\u6211\u958B\u59CB\u5BB3\u6015\u81EA\u5DF1\u5FD8\u8A18\u600E\u9EBC\u601D\u8003","permalink":"/blog/ai-coding"},"nextItem":{"title":"Vibe Coding \u5F88\u723D\uFF0C\u4F46\u5225\u8B93 AI \u96B1\u85CF\u7684\u300C\u5B89\u5168\u5730\u96F7\u300D\u6BC0\u6389\u4F60\u7684\u7522\u54C1","permalink":"/blog/ai-vibe-coding"}},"content":"\u5C0F\u5915\u7D42\u65BC\u51FA\u6708\u4E2D\u4E86\uFF01\u56DE\u9867\u9019\u4E00\u500B\u6708\uFF0C\u65E5\u5B50\u904E\u5F97\u65E2\u75B2\u618A\u53C8\u5145\u5BE6\uFF0C\u9084\u5145\u6EFF\u4E86\u5404\u7A2E\u300C\u9A5A\u559C\u300D\u3002\\n\\n## \u4E09\u68F2\u6230\u58EB\u7684\u65E5\u5E38\\n\u9019\u6BB5\u6642\u9593\uFF0C\u6211\u6210\u4E86\u540D\u526F\u5176\u5BE6\u7684\u300C\u4E09\u68F2\u6230\u58EB\u300D\uFF1A  \\n\u6BCF\u5929\u5728\u516C\u53F8\u3001\u6708\u4E2D\u3001\u5BB6\u88E1\u4E09\u500B\u9EDE\u4E4B\u9593\u4F86\u56DE\u5954\u6CE2\uFF0C\u9664\u4E86\u8981\u61C9\u4ED8\u516C\u53F8\u88E1\u7684\u7169\u5FC3\u4E8B\uFF0C\u9084\u8981\u6293\u7DCA\u6642\u9593\u5B78\u7FD2\u80B2\u5152\u6280\u80FD\u3002  \\n\\n\\n`{`/* truncate */`}`\\n\\n\\n\u96D6\u7136\u7D2F\u5230\u5FEB\u88AB\u75B2\u52DE\u8F5F\u70B8\uFF0C\u4F46\u6536\u7A6B\u4E5F\u5F88\u591A\u2014\u2014\u5F9E\u600E\u9EBC\u9935\u5976\u3001\u6D17\u6FA1\uFF0C\u5230\u89E3\u8B80\u5BF6\u5BF6\u7684\u9700\u6C42\uFF0C\u9019\u4E9B\u90FD\u662F\u4EE5\u524D\u96E3\u4EE5\u60F3\u50CF\u7684\u6311\u6230\u3002  \\n\\n\u4EE5\u524D\u7E3D\u89BA\u5F97\u73A9\u5225\u4EBA\u7684\u5C0F\u5B69\u5F88\u7C21\u55AE\uFF0C\u81EA\u5DF1\u52D5\u624B\u624D\u767C\u73FE\uFF1A\u8981\u7167\u9867\u597D\u4E00\u500B\u751F\u547D\u771F\u7684\u597D\u96E3\u3002\u770B\u8457\u5C0F\u5915\u559D\u5B8C\u5976\u626D\u4F86\u626D\u53BB\u4E0D\u7761\u89BA\uFF0C\u5230\u5E95\u662F\u8981\u63DB\u5C3F\u5E03\u9084\u662F\u6C92\u5403\u98FD\uFF1F\u6BCF\u4E00\u7D44\u80A2\u9AD4\u52D5\u4F5C\u90FD\u662F\u5BC6\u78BC\uFF0C\u96D6\u7136\u71D2\u8166\uFF0C\u4F46\u4E5F\u5F88\u6709\u8DA3\u3002\\n\\n## \u51FA\u6708\u4E2D\u5F8C\u7684\u6311\u6230\\n\u7136\u800C\uFF0C\u6311\u6230\u624D\u525B\u958B\u59CB\uFF0C\u51FA\u6708\u4E2D\u5F8C\u6211\u5011\u5373\u5C07\u9762\u81E8\u66AB\u6642\u7684\u5206\u9694\u3002  \\n\u56E0\u70BA\u898F\u5283\u7684\u95DC\u4FC2\uFF0C\u5C0F\u5915\u8981\u56DE\u53F0\u5317\u9577\u4F4F\uFF0C\u6211\u4E5F\u6B63\u5F0F\u9032\u5165\u300C\u5047\u65E5\u7238\u7238\u300D\u7684\u6A21\u5F0F\u3002\u60F3\u5230\u9019\u88E1\u96E3\u514D\u6709\u4E9B\u611F\u50B7\uFF0C\u4F46\u5728\u9019\u8F49\u63DB\u7684\u904E\u7A0B\u4E2D\uFF0C\u6211\u66F4\u6DF1\u523B\u9AD4\u6703\u5230\uFF1A**\u80B2\u5152\u89C0\u5FF5\u7684\u78B0\u649E\uFF0C\u624D\u662F\u6700\u8003\u9A57\u4EBA\u7684\u4FEE\u884C\u3002**\\n\\n## \u8207\u5CB3\u6BCD\u7684\u80B2\u5152\u89C0\u5FF5\u5DEE\u7570\\n\u6211\u5CB3\u6BCD\u662F\u4E00\u4F4D\u5C08\u696D\u4FDD\u6BCD\uFF0C\u9818\u6709\u8B49\u7167\uFF0C\u6700\u8FD1\u525B\u5E36\u5B8C\u4E00\u5C0D\u96D9\u80DE\u80CE\uFF0C\u672C\u4F86\u6253\u7B97\u9032\u5165\u9000\u4F11\u751F\u6D3B\uFF0C\u525B\u597D\u5C0F\u5915\u300C\u5831\u5230\u300D\uFF0C\u8B93\u5979\u7684\u9000\u4F11\u751F\u6D3B\u4E00\u9EDE\u90FD\u4E0D\u7121\u804A\u3002  \\n\\n\u4F46\u4E5F\u56E0\u70BA\u9577\u8F29\u6709\u8457\u6DF1\u539A\u7684\u300C\u5BE6\u6230\u7D93\u9A57\u300D\uFF0C\u8B93\u6211\u5011\u5728\u6708\u4E2D\u5B78\u5230\u7684\u73FE\u4EE3\u8B77\u7406\u89C0\u5FF5\uFF0C\u9762\u81E8\u4E86\u524D\u6240\u672A\u6709\u7684\u6311\u6230\uFF1A\\n\\n1. **\u75F1\u5B50\u7C89\u624D\u662F\u842C\u80FD\uFF0C\u5C41\u5C41\u818F\u90FD\u662F\u5316\u5B78\uFF1F**  \\n   \u95DC\u65BC\u5C41\u5C41\u8B77\u7406\uFF0C\u5CB3\u6BCD\u5805\u6301\u4F7F\u7528\u5979\u90A3\u300C\u52A0\u4E86\u4E2D\u85E5\u3001\u6BD4\u8F03\u5929\u7136\u300D\u7684\u75F1\u5B50\u7C89\uFF0C\u76F4\u63A5\u62D2\u7D55\u4E86\u6211\u5011\u6E96\u5099\u7684\u5C41\u5C41\u818F\u3002\\n\\n2. **\u6BCD\u5976\u81F3\u4E0A\uFF0C\u914D\u65B9\u5976\u662F\u5916\u9053\uFF1F**  \\n   \u5728\u6708\u4E2D\u6642\uFF0C\u56E0\u70BA\u5C0F\u5915\u4FBF\u4FBF\u6B21\u6578\u904E\u591A\uFF0C\u91AB\u751F\u5EFA\u8B70\u5148\u63DB\u7121\u4E73\u7CD6\u914D\u65B9\u5976\u89C0\u5BDF\u3002\u6C92\u60F3\u5230\u4E00\u56DE\u53F0\u5317\uFF0C\u5CB3\u6BCD\u7ACB\u523B\u4E0B\u4EE4\u300C\u5168\u9762\u6539\u56DE\u6BCD\u5976\u300D\uFF0C\u751A\u81F3\u8A8D\u70BA\u5BF6\u5BF6\u62C9\u809A\u5B50\u662F\u56E0\u70BA\u5ABD\u5ABD\u4E82\u5403\uFF08\u5B8C\u5168\u7121\u8996\u6708\u4E2D\u71DF\u990A\u5E2B\u914D\u904E\u7684\u6708\u5B50\u9910\uFF0C\u5979\u4E00\u76F4\u89BA\u5F97\u6708\u5B50\u9910\u6C92\u5979\u716E\u7684\u88DC\uFF09\u3002\\n\\n3. **\u4E73\u6DB2\u6709\u5BB3\u8AD6\uFF1A\u6D17\u5B8C\u6FA1\u64E6\u4E73\u6DB2\uFF1F\u6211\u90FD\u6C92\u5728\u7528\u7684**  \\n   \u5EFA\u8B70\u6D17\u6FA1\u5F8C\u5E6B\u5BF6\u5BF6\u5857\u500B\u4E73\u6DB2\uFF0C\u63DB\u4F86\u7684\u662F\u4E00\u53E5\uFF1A\u300C\u6211\u5E36\u904E\u9019\u9EBC\u591A\u5C0F\u5B69\u90FD\u6C92\u5728\u64E6\uFF0C\u90A3\u90FD\u662F\u5316\u5B78\u7684\u6771\u897F\uFF0C\u5C0D\u5C0F\u5B69\u4E0D\u597D\u3002\u300D\u807D\u5F97\u6211\u53EA\u80FD\u4E7E\u7B11\u3002\\n\\n4. **\u80A5\u7682\u7D55\u5C0D\u512A\u65BC\u6C90\u6D74\u4E73**  \\n   \u5CB3\u6BCD\u62FF\u51FA\u4E00\u584A\u80A5\u7682\u8981\u6211\u5E36\u56DE\u5BB6\uFF0C\u5F37\u8ABF\u5979\u90FD\u7528\u9019\u500B\u6D17\uFF0C\u9084\u5ACC\u68C4\u6211\u5011\u8CB7\u7684\u6C90\u6D74\u7522\u54C1\u3002  \\n   \u6211\u63D0\u9192\u5979\uFF1A\u300C\u80A5\u7682\u88E1\u6709\u9999\u7CBE\uFF0C\u5C0F\u5915\u73FE\u5728\u4E0D\u9069\u5408\u78B0\u3002\u300D\u5979\u537B\u56DE\u6211\uFF1A\u300C\u4F46\u9019\u662F\u5B30\u5152\u5C08\u7528\u7684\u554A\uFF01\u300D  \\n   \u6211\u53EA\u597D\u7121\u5948\u53CD\u64CA\uFF1A\u300C\u6211\u7684\u4E73\u6DB2\u4E5F\u662F\u5B30\u5152\u7528\u7684\u554A...\u300D\u6700\u5F8C\u53EA\u80FD\u5728\u5C37\u5C2C\u4E2D\u4E0D\u4E86\u4E86\u4E4B\u3002\\n\\n## \u5FC3\u60C5\u8207\u671F\u5F85\\n\u8001\u5BE6\u8AAA\uFF0C\u5FC3\u88E1\u771F\u7684\u5F88\u4E0D\u723D\uFF0C\u4F46\u7919\u65BC\u5C0D\u65B9\u662F\u9577\u8F29\u53C8\u662F\u5E6B\u5FD9\u5E36\u5C0F\u5B69\uFF0C\u771F\u7684\u96E3\u4EE5\u8A00\u8AAA\u3002  \\n\u6211\u6253\u7B97\u5148\u51B7\u975C\u89C0\u5BDF\u4E00\u9031\uFF0C\u770B\u770B\u5BF6\u5BF6\u9069\u61C9\u7684\u60C5\u6CC1\u3002\\n\\n---\\n\\n**\u5C0F\u5915\uFF0C\u4F60\u8981\u6490\u4F4F\u554A\uFF01\u7238\u7238\u4E0B\u79AE\u62DC\u5C31\u53BB\u63A5\u4F60\u3002**"},{"id":"ai-vibe-coding","metadata":{"permalink":"/blog/ai-vibe-coding","source":"@site/blog/2026-04-23-ai-vibe-coding.md","title":"Vibe Coding \u5F88\u723D\uFF0C\u4F46\u5225\u8B93 AI \u96B1\u85CF\u7684\u300C\u5B89\u5168\u5730\u96F7\u300D\u6BC0\u6389\u4F60\u7684\u7522\u54C1","description":"\u6700\u8FD1\u958B\u767C\u5708\u6700\u8FF7\u4EBA\u7684\u8A5E\u83AB\u904E\u65BC Vibe Coding\u2014\u2014\u6253\u5E7E\u53E5\u8A71\uFF0C\u770B\u8457 AI \u5E6B\u4F60\u628A\u529F\u80FD\u751F\u51FA\u4F86\uFF0C\u6E2C\u8A66\u6C92\u554F\u984C\u5C31\u5149\u901F\u90E8\u7F72\u3002\u4EE5\u524D\u8981\u82B1\u597D\u5E7E\u5929\u7684\u5C08\u6848\uFF0C\u73FE\u5728\u4E00\u500B\u4E0B\u5348\u5C31\u80FD\u641E\u5B9A\u3002","date":"2026-04-23T05:10:26.330Z","tags":[{"inline":true,"label":"security","permalink":"/blog/tags/security"},{"inline":true,"label":"ai","permalink":"/blog/tags/ai"}],"readingTime":3.75,"hasTruncateMarker":false,"authors":[{"name":"Liwen","title":"Digital Architect / Full Stack Developer","url":"https://github.com/liwenchiou","imageURL":"https://github.com/liwenchiou.png","key":"liwen","page":null}],"frontMatter":{"slug":"ai-vibe-coding","title":"Vibe Coding \u5F88\u723D\uFF0C\u4F46\u5225\u8B93 AI \u96B1\u85CF\u7684\u300C\u5B89\u5168\u5730\u96F7\u300D\u6BC0\u6389\u4F60\u7684\u7522\u54C1","date":"2026-04-23T05:10:26.330Z","authors":["liwen"],"tags":["security","ai"]},"unlisted":false,"prevItem":{"title":"\u5C0F\u5915\u51FA\u6708\u4E2D\u8A18","permalink":"/blog/weekend-dad-full-time-heart"},"nextItem":{"title":"\u96F2\u7AEF\u908A\u7DE3\u7684\u6298\u7FFC\uFF1ANext.js \u90E8\u7F72\u5230 Cloudflare Pages \u7684 48 \u5C0F\u6642\u596E\u9B25\u5BE6\u9304","permalink":"/blog/\u96F2\u7AEF\u908A\u7DE3\u7684\u6298\u7FFCnextjs-\u90E8\u7F72\u5230-cloudflare-pages-\u7684-48-\u5C0F\u6642\u596E\u9B25\u5BE6\u9304"}},"content":"\u6700\u8FD1\u958B\u767C\u5708\u6700\u8FF7\u4EBA\u7684\u8A5E\u83AB\u904E\u65BC **Vibe Coding**\u2014\u2014\u6253\u5E7E\u53E5\u8A71\uFF0C\u770B\u8457 AI \u5E6B\u4F60\u628A\u529F\u80FD\u751F\u51FA\u4F86\uFF0C\u6E2C\u8A66\u6C92\u554F\u984C\u5C31\u5149\u901F\u90E8\u7F72\u3002\u4EE5\u524D\u8981\u82B1\u597D\u5E7E\u5929\u7684\u5C08\u6848\uFF0C\u73FE\u5728\u4E00\u500B\u4E0B\u5348\u5C31\u80FD\u641E\u5B9A\u3002\\n\\n\u8AAA\u771F\u7684\uFF0C\u9019\u7A2E\u300C\u8166\u529B\u5373\u7522\u529B\u300D\u7684\u611F\u89BA\u975E\u5E38\u723D\u3002\u4F46\u5C31\u5728\u9019\u7A2E\u9AD8\u901F\u751F\u7522\u7684\u6D41\u7A0B\u4E2D\uFF0C\u6211\u6CE8\u610F\u5230\u4E86\u4E00\u500B\u96B1\u5F62\u5371\u6A5F\uFF1A**\u6D41\u7A0B\u592A\u9806\u4E86\uFF0C\u9806\u5230\u8B93\u6211\u5011\u5FD8\u8A18\u4E86\u8EAB\u70BA\u958B\u767C\u8005\u6700\u57FA\u672C\u7684\u300C\u9632\u79A6\u672C\u80FD\u300D\u3002**\\n\\n\\n`{`/* truncate */`}`\\n\\n\\n\u5982\u679C\u4F60\u4E5F\u71B1\u8877\u65BC Vibe Coding\uFF0C\u9019\u7BC7\u300C\u4FDD\u547D\u6307\u5357\u300D\u4F60\u4E00\u5B9A\u8981\u52A0\u5165\u6536\u85CF\u3002\\n\\n---\\n\\n## \u{1F6D1} \u7B2C\u4E00\u95DC\uFF1A\u4F60\u7684 API Key\uFF0C\u6B63\u5728 GitHub \u4E0A\u88F8\u5954\u55CE\uFF1F\\n\\n\u9019\u662F\u6700\u5E38\u898B\u3001\u4E5F\u6700\u5BB9\u6613\u5C0E\u81F4\u300C\u4FE1\u7528\u5361\u5237\u7206\u300D\u7684\u5931\u8AA4\u3002\\n\\n\u7576\u4F60\u53EB AI \u5FEB\u901F\u4E32\u63A5 OpenAI \u6216 Stripe API \u6642\uFF0C\u5B83\u751F\u6210\u7684\u7BC4\u4F8B\u7A0B\u5F0F\u78BC\u70BA\u4E86\u8B93\u4F60\u76F4\u63A5\u8DD1\u901A\uFF0C\u5F80\u5F80\u6703\u9577\u9019\u6A23\uFF1A\\n\\n```javascript\\n/* \u26A0\uFE0F \u9019\u662F\u81EA\u6BBA\u5F0F\u5BEB\u6CD5\uFF1A\u5343\u842C\u5225\u5B78 */\\nconst openai = new OpenAI({\\n  apiKey: \\"sk-proj-xxxxxxxxxxxxxxxxxxxxxxxx\\", // AI \u70BA\u4E86\u65B9\u4FBF\uFF0C\u76F4\u63A5\u5E6B\u4F60\u586B\u5728\u9019\u88E1\u4E86\\n});\\n```\\n\\n\u5982\u679C\u4F60\u76F4\u63A5 `git push` \u4E0A GitHub\uFF0C\u4E0D\u5230\u4E00\u5206\u9418\uFF0C\u5168\u4E16\u754C\u7684\u722C\u87F2\u6A5F\u5668\u4EBA\u90FD\u6703\u62FF\u5230\u4F60\u7684\u91D1\u9470\uFF0C\u958B\u59CB\u760B\u72C2\u76DC\u5237\u3002\\n\\n> [!WARNING]\\n> **\u7DCA\u6025\u6551\u63F4\uFF1A** \u5982\u679C\u91D1\u9470\u5DF2\u7D93 push \u51FA\u53BB\uFF0C\u8ACB\u7B2C\u4E00\u6642\u9593\u53BB\u5F8C\u53F0 **\u5EE2\u6389 (Rotate) \u90A3\u652F Key**\uFF01\u300C\u522A\u6389 commit\u300D\u662F\u6551\u4E0D\u4E86\u4F60\u7684\uFF0C\u56E0\u70BA Git \u7684\u6B77\u53F2\u7D00\u9304\u6703\u6C38\u9060\u7559\u5B58\u3002\\n\\n### \u2705 \u6B63\u78BA\u7684\u512A\u96C5\u59FF\u52E2\uFF1A\\n\u8ACB\u628A\u91D1\u9470\u653E\u9032 `.env` \u6A94\u6848\uFF0C\u4E26\u56B4\u683C\u6AA2\u67E5\u4F60\u7684 `.gitignore`\u3002\\n\\n\u5982\u679C\u4F60\u7684\u5C08\u6848\u898F\u6A21\u8F03\u5927\uFF0C\u5F37\u70C8\u5EFA\u8B70\u6539\u7528 **[Infisical](https://infisical.com/)** \u6216 **[AWS Secrets Manager](https://aws.amazon.com/secrets-manager/)** \u9019\u7A2E\u5C08\u9580\u7684\u52A0\u5BC6\u7BA1\u7406\u5E73\u53F0\uFF0C\u9019\u80FD\u8B93\u4F60\u5373\u4FBF\u4E0D\u5C0F\u5FC3\u6D29\u6F0F\u4E86\u74B0\u5883\u8B8A\u6578\u6A94\u6848\uFF0C\u91D1\u9470\u4F9D\u7136\u5B89\u5168\u7121\u865E\u3002\\n\\n> [!TIP]\\n> **Next.js \u8B66\u8A9E\uFF1A** \u5343\u842C\u5225\u5728\u79C1\u5BC6\u91D1\u9470\u524D\u7DB4\u52A0\u4E0A `NEXT_PUBLIC_`\uFF0C\u5426\u5247\u5B83\u6703\u88AB\u6253\u5305\u9032\u524D\u7AEF\u3002\u5230\u6642\u5019\u8B80\u8005\u53EA\u8981\u6309\u4E00\u4E0B F12\uFF0C\u4F60\u7684\u79C1\u9470\u5C31\u6703\u76F4\u63A5\u5728\u700F\u89BD\u5668\u88E1\u8DDF\u4F60\u62DB\u624B\u3002\\n\\n---\\n\\n## \u{1F6E1}\uFE0F \u7B2C\u4E8C\u95DC\uFF1AAI \u53EA\u7BA1\u529F\u80FD\uFF0C\u5B83\u4E0D\u6703\u4E3B\u52D5\u300C\u64CB\u58DE\u4EBA\u300D\\n\\nAI \u7684\u5929\u6027\u662F\u300C\u89E3\u6C7A\u554F\u984C\u300D\uFF0C\u5B83\u4E0D\u592A\u6703\u4E3B\u52D5\u8003\u616E\u5230\u300C\u88AB\u60E1\u641E\u7684\u5834\u666F\u300D\u3002\u4F8B\u5982\u4E00\u500B\u7C21\u55AE\u7684\u8CC7\u6599\u5EAB\u67E5\u8A62\uFF0CAI \u53EF\u80FD\u6703\u7D66\u4F60\u9019\u6A23\u7684 code\uFF1A\\n\\n```python\\n# \u7D93\u5178\u7684 SQL \u6CE8\u5165\u6EAB\u5E8A\\ndb.execute(f\\"INSERT INTO notes VALUES (\'{user_input_text}\')\\")\\n```\\n\\n\u9019\u5728\u8CC7\u5B89\u9818\u57DF\u53EB\u505A **SQL Injection**\u3002\u53EA\u8981\u6709\u4EBA\u8F38\u5165\u4E00\u53E5\u7279\u6B8A\u7684\u4EE3\u78BC\uFF0C\u4F60\u7684\u6574\u500B\u8CC7\u6599\u5EAB\u5167\u5BB9\u53EF\u80FD\u5C31\u6703\u88AB\u6D17\u52AB\u4E00\u7A7A\u3002\\n\\n**Vibe Coder \u5FC5\u9808\u5EFA\u7ACB\u7684\u7FD2\u6163\uFF1A**\\n*   **\u4E0D\u4FE1\u4EFB\u4EFB\u4F55\u8F38\u5165**\uFF1A\u6C38\u9060\u6AA2\u67E5\u4F7F\u7528\u8005\u50B3\u904E\u4F86\u7684\u6587\u5B57\u3002\\n*   **\u9650\u5236\u983B\u7387 (Rate Limiting)**\uFF1A\u5982\u679C\u6709\u4EBA\u5BEB\u500B\u8FF4\u5708\u72C2\u704C\u4F60\u7684 API\uFF0C\u4F60\u7684\u5E33\u55AE\u6703\u6BD4\u4F60\u7684\u7A0B\u5F0F\u78BC\u8DD1\u5F97\u5FEB\u3002\\n\\n---\\n\\n## \u{1F50D} \u7B2C\u4E09\u95DC\uFF1A\u90E8\u7F72\u5F8C\u7684\u300C\u96B1\u5F62\u5F8C\u9580\u300D\\n\\n\u73FE\u4EE3\u90E8\u7F72\u5E73\u53F0\uFF08\u5982 Vercel, Railway\uFF09\u8B93\u4E0A\u7DDA\u8B8A\u5F97\u592A\u7C21\u55AE\u3002\u4F46\u7C21\u55AE\u7684\u80CC\u5F8C\uFF0C\u9019\u5169\u500B\u5730\u65B9\u6700\u5BB9\u6613\u8E29\u96F7\uFF1A\\n\\n1.  **Debug \u6A21\u5F0F\u5FD8\u4E86\u95DC**\uFF1A\u958B\u8457 Debug \u6A21\u5F0F\u4E0A\u7DDA\uFF0C\u5C31\u50CF\u662F\u628A\u5BB6\u88E1\u7684\u5E73\u9762\u5716\u8207\u4FDD\u96AA\u7BB1\u5BC6\u78BC\u8CBC\u5728\u5927\u9580\u53E3\u3002\u5B83\u6703\u628A\u6A94\u6848\u8DEF\u5F91\u3001\u74B0\u5883\u8B8A\u6578\u8A73\u7D30\u5730\u5831\u7D66\u4F7F\u7528\u8005\uFF08\u548C\u99ED\u5BA2\uFF09\u770B\u3002\\n2.  **\u8CC7\u6599\u5EAB\u516C\u958B\u5B58\u53D6**\uFF1ASupabase \u6216 Firebase \u9810\u8A2D\u70BA\u4E86\u65B9\u4FBF\u958B\u767C\uFF0C\u6709\u6642\u6703\u958B\u653E\u6B0A\u9650\u3002**\u4E0A\u7DDA\u524D\u8ACB\u52D9\u5FC5\u6AA2\u67E5 Row Level Security (RLS)**\uFF0C\u78BA\u4FDD\u90A3\u662F\u9396\u597D\u7684\u3002\\n\\n---\\n\\n## \u{1F9F0} Vibe Coder \u7684\u5B89\u5168\u767E\u5BF6\u7BB1\\n\\n\u70BA\u4E86\u8B93\u4F60\u5B89\u5FC3\u5730\u300CVibe\u300D\uFF0C\u5EFA\u8B70\u5728\u5DE5\u4F5C\u6D41\u4E2D\u52A0\u5165\u9019\u5E7E\u4F4D\u300C\u81EA\u52D5\u5316\u4FDD\u93E2\u300D\uFF1A\\n\\n*   **[Trufflehog (\u91D1\u9470\u7375\u4EBA)](https://github.com/trufflesecurity/trufflehog)**\uFF1A\u5C08\u9580\u6383\u63CF\u4F60\u7684 Git \u6B77\u53F2\uFF0C\u7FFB\u51FA\u90A3\u4E9B\u88AB\u4F60\u907A\u5FD8\u5728\u820A\u7248\u672C\u88E1\u7684\u79D8\u5BC6\u3002\\n*   **[Snyk (\u5957\u4EF6\u6F0F\u6D1E\u96F7\u9054)](https://snyk.io/)** / **[Dependabot](https://github.com/dependabot)**\uFF1AGitHub \u5167\u5EFA\u6216\u5916\u639B\u3002\u5B83\u5011\u6703\u76E3\u63A7\u4F60\u7684\u5957\u4EF6\u5EAB\uFF0C\u767C\u73FE\u6F0F\u6D1E\u6642\u6703\u76F4\u63A5\u767C\u4E00\u500B PR \u5E6B\u4F60\u4FEE\u597D\u3002\\n*   **[Gitleaks](https://github.com/gitleaks/gitleaks)**\uFF1A\u9019\u662F\u6700\u5F8C\u4E00\u9053\u9632\u7DDA\uFF0C\u5982\u679C\u4F60\u60F3\u5728\u672C\u5730\u7AEF\u6514\u622A\u5931\u8AA4\uFF0C\u5B83\u53EF\u4EE5\u5728\u4F60 `commit` \u7684\u90A3\u4E00\u523B\u963B\u6B62\u4F60\u628A Key \u50B3\u51FA\u53BB\u3002\\n*   **[GitHub Secret Scanning](https://docs.github.com/en/code-security/secret-scanning/about-secret-scanning)**\uFF1AGitHub \u5B98\u65B9\u5167\u5EFA\u7684\u5F37\u5927\u529F\u80FD\uFF0C\u80FD\u7B2C\u4E00\u6642\u9593\u963B\u65B7\u6D29\u6F0F\u3002\\n\\n---\\n\\n## \u{1F4A1} \u7E3D\u7D50\uFF1A\u5FEB\u96D6\u597D\uFF0C\u4F46\u5B89\u5168\u4E0D\u80FD\u7701\\n\\nVibe Coding \u8B93\u6BCF\u500B\u4EBA\u90FD\u80FD\u6210\u70BA\u300C\u6578\u4F4D\u5275\u4F5C\u8005\u300D\uFF0C\u9019\u662F\u4E00\u5834\u6C11\u4E3B\u5316\u9769\u547D\u3002\u4F46\u9019\u4E5F\u4EE3\u8868\uFF0C\u4EE5\u524D\u5DE5\u7A0B\u5E2B\u624D\u6703\u78B0\u5230\u7684\u70B8\u5F48\uFF0C\u73FE\u5728\u6211\u5011\u6BCF\u500B\u4EBA\u90FD\u8981\u61C2\u5F97\u62C6\u3002\\n\\n**\u8A18\u4F4F\u9019\u500B\u300C\u5B89\u5168\u6E05\u55AE\u300D\uFF1A**\\n1.  **\u91D1\u9470\u5FC5\u9032 `.env`**\uFF0C\u4E14\u5FC5\u9808\u52A0\u5165 `.gitignore`\u3002\\n2.  **\u4E0D\u4FE1\u4EFB\u8F38\u5165**\uFF0C\u4E00\u5B9A\u8981\u505A\u5167\u5BB9\u9A57\u8B49\u3002\\n3.  **\u78BA\u8A8D\u6B0A\u9650**\uFF0C\u4E0A\u7DDA\u524D\u95DC\u9589 Debug \u8207\u8CC7\u6599\u5EAB\u516C\u958B\u6B0A\u9650\u3002\\n4.  **\u5B9A\u671F\u6AA2\u6838**\uFF0C\u8DD1\u4E00\u4E0B `npm audit` \u770B\u770B\u5957\u4EF6\u5065\u4E0D\u5065\u5EB7\u3002\\n\\n*\u505A\u7522\u54C1\u672C\u4F86\u5C31\u6709\u98A8\u96AA\uFF0C\u4F46\u9019\u4E9B\u4F4E\u7D1A\u932F\u8AA4\u4E0D\u503C\u5F97\u4F60\u5192\u96AA\u3002*\\n\\n---"},{"id":"\u96F2\u7AEF\u908A\u7DE3\u7684\u6298\u7FFCnextjs-\u90E8\u7F72\u5230-cloudflare-pages-\u7684-48-\u5C0F\u6642\u596E\u9B25\u5BE6\u9304","metadata":{"permalink":"/blog/\u96F2\u7AEF\u908A\u7DE3\u7684\u6298\u7FFCnextjs-\u90E8\u7F72\u5230-cloudflare-pages-\u7684-48-\u5C0F\u6642\u596E\u9B25\u5BE6\u9304","source":"@site/blog/2026-04-23-\u96F2\u7AEF\u908A\u7DE3\u7684\u6298\u7FFCnextjs-\u90E8\u7F72\u5230-cloudflare-pages-\u7684-48-\u5C0F\u6642\u596E\u9B25\u5BE6\u9304.md","title":"\u96F2\u7AEF\u908A\u7DE3\u7684\u6298\u7FFC\uFF1ANext.js \u90E8\u7F72\u5230 Cloudflare Pages \u7684 48 \u5C0F\u6642\u596E\u9B25\u5BE6\u9304","description":"\u5728 Web \u958B\u767C\u7684\u4E16\u754C\u88E1\uFF0C\u6211\u5011\u901A\u5E38\u6703\u5F9E Vercel \u958B\u59CB\u3002\u5B83\u5F88\u7F8E\u3001\u5F88\u5FEB\u3001\u5F88\u6709\u8CEA\u611F\uFF0C\u5C31\u50CF\u662F\u4E00\u500B\u7CBE\u5FC3\u88DD\u6F62\u7684\u8C6A\u83EF\u516C\u5BD3\u3002\u4F46\u96A8\u8457\u5C08\u6848\u6210\u9577\uFF0C\u6211\u5011\u958B\u59CB\u5728\u60F3\uFF1A\u6709\u6C92\u6709\u90A3\u7A2E\u65E2\u80FD\u64C1\u6709\u6975\u81F4\u6027\u80FD\uFF0C\u6210\u672C\u53C8\u66F4\u5E73\u6613\u8FD1\u4EBA\u7684\u300C\u81EA\u7531\u4E4B\u5730\u300D\uFF1F","date":"2026-04-23T00:56:25.022Z","tags":[{"inline":true,"label":"cloudflare","permalink":"/blog/tags/cloudflare"},{"inline":true,"label":"NextJs","permalink":"/blog/tags/next-js"}],"readingTime":4.85,"hasTruncateMarker":false,"authors":[{"name":"Liwen","title":"Digital Architect / Full Stack Developer","url":"https://github.com/liwenchiou","imageURL":"https://github.com/liwenchiou.png","key":"liwen","page":null}],"frontMatter":{"slug":"\u96F2\u7AEF\u908A\u7DE3\u7684\u6298\u7FFCnextjs-\u90E8\u7F72\u5230-cloudflare-pages-\u7684-48-\u5C0F\u6642\u596E\u9B25\u5BE6\u9304","title":"\u96F2\u7AEF\u908A\u7DE3\u7684\u6298\u7FFC\uFF1ANext.js \u90E8\u7F72\u5230 Cloudflare Pages \u7684 48 \u5C0F\u6642\u596E\u9B25\u5BE6\u9304","date":"2026-04-23T00:56:25.022Z","authors":["liwen"],"tags":["cloudflare","NextJs"]},"unlisted":false,"prevItem":{"title":"Vibe Coding \u5F88\u723D\uFF0C\u4F46\u5225\u8B93 AI \u96B1\u85CF\u7684\u300C\u5B89\u5168\u5730\u96F7\u300D\u6BC0\u6389\u4F60\u7684\u7522\u54C1","permalink":"/blog/ai-vibe-coding"},"nextItem":{"title":"\u5192\u540D\u9802\u66FF\u75C7\u5019\u7FA4 (Imposter Syndrome) \u6DF1\u5EA6\u89E3\u6790","permalink":"/blog/imposter-syndrome"}},"content":"\u5728 Web \u958B\u767C\u7684\u4E16\u754C\u88E1\uFF0C\u6211\u5011\u901A\u5E38\u6703\u5F9E Vercel \u958B\u59CB\u3002\u5B83\u5F88\u7F8E\u3001\u5F88\u5FEB\u3001\u5F88\u6709\u8CEA\u611F\uFF0C\u5C31\u50CF\u662F\u4E00\u500B\u7CBE\u5FC3\u88DD\u6F62\u7684\u8C6A\u83EF\u516C\u5BD3\u3002\u4F46\u96A8\u8457\u5C08\u6848\u6210\u9577\uFF0C\u6211\u5011\u958B\u59CB\u5728\u60F3\uFF1A\u6709\u6C92\u6709\u90A3\u7A2E\u65E2\u80FD\u64C1\u6709\u6975\u81F4\u6027\u80FD\uFF0C\u6210\u672C\u53C8\u66F4\u5E73\u6613\u8FD1\u4EBA\u7684\u300C\u81EA\u7531\u4E4B\u5730\u300D\uFF1F\\n\\n\u65BC\u662F\uFF0C\u6211\u5011\u628A\u76EE\u5149\u6295\u5411\u4E86 Cloudflare\u3002\u9019\u5169\u5929\uFF0C\u6211\u5011\u5C31\u50CF\u662F\u4E00\u7FA4\u8A66\u5716\u5E36\u8457\u884C\u674E\u5F9E Vercel \u642C\u5BB6\u5230 Cloudflare \u908A\u7DE3\u8A08\u7B97\u4E4B\u57CE\u7684\u65C5\u4EBA\u3002\u96D6\u7136\u6700\u7D42\u6211\u5011\u56E0\u70BA\u884C\u674E\u592A\u91CD\u800C\u66AB\u6642\u64A4\u9000\uFF0C\u4F46\u9019\u5834\u300C\u5931\u6557\u300D\u7559\u4E0B\u7684\u7D93\u9A57\u6559\u8A13\uFF0C\u6216\u8A31\u6BD4\u6210\u529F\u642C\u5BB6\u66F4\u503C\u5F97\u8A18\u9304\u3002\\n\\n\\n`{`/* truncate */`}`\\n\\n\\n## \u70BA\u4EC0\u9EBC\u60F3\u544A\u5225 Vercel\uFF0C\u64C1\u62B1 Cloudflare\uFF1F\\n\\nLiwenBlog CMS \u96D6\u7136\u76EE\u524D\u5728 Vercel \u904B\u884C\u826F\u597D\uFF0C\u4F46\u6211\u5011\u5FC3\u4E2D\u4E00\u76F4\u6709\u500B\u300C\u908A\u7DE3\u5922\u300D\uFF1A\\n1. **\u6253\u7834\u6D41\u91CF\u7126\u616E**\uFF1AVercel \u7684\u5546\u696D\u65B9\u6848\u96D6\u7136\u5F37\u5927\uFF0C\u4F46\u5C0D\u65BC\u500B\u4EBA\u6216\u5C0F\u578B\u5DE5\u4F5C\u5BA4\u4F86\u8AAA\uFF0CCloudflare Pages \u90A3\u8FD1\u4E4E\u7121\u9650\u7684\u8ACB\u6C42\u6578\u548C\u66F4\u900F\u660E\u7684\u6210\u672C\u7D50\u69CB\u66F4\u5177\u5438\u5F15\u529B\u3002\\n2. **\u8FFD\u6C42\u300C\u771F\u6B63\u7684\u300D\u908A\u7DE3**\uFF1A\u6211\u5011\u5E0C\u671B\u5728\u96E2\u4F7F\u7528\u8005\u6700\u8FD1\u7684\u5730\u65B9\uFF08Edge Runtime\uFF09\u8655\u7406\u8CC7\u6599\uFF0C\u8B93\u90E8\u843D\u683C\u7684\u6BCF\u4E00\u6BEB\u79D2\u90FD\u80FD\u88AB\u7BC0\u7701\u4E0B\u4F86\u3002\\n3. **\u6280\u8853\u68E7\u7684\u7D42\u6975\u6574\u5408**\uFF1A\u65E2\u7136\u6211\u5011\u7684\u6578\u64DA\u5EAB\u5728 Supabase\uFF0C\u5982\u679C\u80FD\u628A Next.js \u4E5F\u653E\u5728 Cloudflare \u4E0A\uFF0C\u5C31\u80FD\u69CB\u5EFA\u51FA\u4E00\u500B\u5B8C\u5168\u53BB\u4E2D\u5FC3\u5316\u3001\u9AD8\u6027\u80FD\u7684\u4E16\u754C\u7D1A\u6280\u8853\u68E7\u3002\\n\\n## \u649E\u4E0A\u90A3\u4E00\u5835\u7246\uFF1A\u6578\u5B57\u80CC\u5F8C\u7684\u7269\u7406\u6975\u9650\\n\\n\u9019\u5834\u5931\u6557\u7684\u6838\u5FC3\u539F\u56E0\uFF0C\u53EF\u4EE5\u7E3D\u7D50\u6210\u4E00\u7D44\u51B7\u51B0\u51B0\u4F46\u73FE\u5BE6\u7684\u6578\u5B57\uFF1A**3MB \u8207 25MB**\u3002\\n\\n\u5728 Cloudflare Pages / Workers \u7684\u74B0\u5883\u4E0B\uFF0C\u6709\u5169\u500B\u6211\u5011\u7121\u6CD5\u8FF4\u907F\u7684\u786C\u6307\u6A19\uFF1A\\n1. **\u55AE\u4E00\u8173\u672C\u9650\u5236 (3MB)**\uFF1A\u6BCF\u500B Worker \u7684\u8173\u672C\u5927\u5C0F\uFF08\u672A\u58D3\u7E2E\uFF09\u4E0D\u80FD\u8D85\u904E 3MB\u3002\u7576\u6211\u5011\u4F7F\u7528 `@opennextjs/cloudflare` \u5C07 Next.js \u7DE8\u8B6F\u5F8C\uFF0C\u6700\u91CD\u8981\u7684\u4F3A\u670D\u5668\u7AEF\u908F\u8F2F\uFF08\u5305\u62EC\u90A3\u4E9B\u91CD\u578B\u7684 SDK\uFF09\u90FD\u6703\u88AB\u6253\u5305\u9032\u9019\u500B\u55AE\u4E00\u6587\u4EF6\u4E2D\u3002\\n2. **\u5168\u5C08\u6848\u7E3D\u5408\u9650\u5236 (25MB)**\uFF1A\u5982\u679C\u4F60\u4F7F\u7528\u7684\u662F\u514D\u8CBB\u7248\uFF0C\u6574\u500B\u5C08\u6848\u7684\u975C\u614B\u8CC7\u7522\u8207\u8173\u672C\u7E3D\u5408\u4E5F\u6709 25MB \u7684\u4E0A\u9650\u3002\u5C0D\u65BC\u4E00\u500B\u5167\u5EFA\u4E86\u5927\u91CF\u8996\u89BA\u7D44\u4EF6\u8207\u7B2C\u4E09\u65B9\u5EAB\u7684\u300C\u65D7\u8266\u7248\u300DCMS \u4F86\u8AAA\uFF0C\u9019\u500B\u6578\u5B57\u6BD4\u60F3\u50CF\u4E2D\u66F4\u8106\u5F31\u3002\\n\\n\u96D6\u7136 **\u4ED8\u8CBB\u7248 (Paid/Standard)** \u53EF\u4EE5\u5C07\u55AE\u4E00\u8173\u672C\u9650\u5236\u653E\u5BEC\u5230 **10MB**\uFF0C\u4F46\u9019\u901A\u5E38\u610F\u5473\u8457\u4F60\u9700\u8981\u6BCF\u500B\u6708\u652F\u4ED8\u984D\u5916\u7684\u8CBB\u7528\uFF0C\u4E14\u4F9D\u7136\u8981\u9762\u5C0D\u4EE3\u78BC\u81A8\u8139\u5C0E\u81F4\u7684\u51B7\u555F\u52D5\uFF08Cold Start\uFF09\u5EF6\u9072\u554F\u984C\u3002\\n\\n### 3. \u74B0\u5883\u7684\u57FA\u56E0\u5DEE\u7570 (The Vercel Lock-in)\\n\u9664\u4E86\u6578\u5B57\u4E0A\u7684\u9650\u5236\uFF0C\u6211\u5011\u66F4\u6DF1\u523B\u611F\u53D7\u5230\u7684\u662F\u300C\u57FA\u56E0\u300D\u7684\u4E0D\u540C\u3002Next.js \u4F5C\u70BA Vercel \u7684\u89AA\u5152\u5B50\uFF0C\u5176 App Router \u7684\u8A31\u591A\u884C\u70BA\u672C\u8CEA\u4E0A\u662F\u70BA\u5176\u539F\u751F\u5E73\u53F0\u91CF\u8EAB\u6253\u9020\u7684\u3002\u642C\u5BB6\u5230 Cloudflare \u4E0D\u53EA\u662F\u63DB\u500B\u4F3A\u670D\u5668\uFF0C\u66F4\u662F\u4E00\u5834\u300C\u53BB Vercel \u5316\u300D\u7684\u67B6\u69CB\u91CD\u69CB\uFF0C\u9019\u7A2E\u6846\u67B6\u8207\u5E73\u53F0\u9593\u7684\u6DF1\u5EA6\u8026\u5408\uFF0C\u8B93\u6211\u5011\u5728\u9077\u79FB\u904E\u7A0B\u4E2D\u5982\u5C65\u8584\u51B0\u3002\\n\\n### 1. SDK \u7684\u91CD\u91CF\\n\u6211\u5011\u7684\u61C9\u7528\u4E2D\u5305\u542B\u4E86\u4E00\u4E9B\u529F\u80FD\u5F37\u5927\u4F46\u4E5F\u300C\u6C89\u91CD\u300D\u7684\u5DE5\u5177\uFF1A\\n- **Shiki**: \u7528\u65BC\u6975\u81F4\u7684\u4EE3\u78BC\u9AD8\u4EAE\u3002\\n- **React-Markdown / Rehype**: \u7528\u65BC\u8655\u7406\u5167\u5BB9\u6E32\u67D3\u3002\\n- **Resend**: \u90F5\u4EF6\u670D\u52D9\u3002\\n- **Supabase SDK**: \u6578\u64DA\u5EAB\u4EA4\u4E92\u7684\u6838\u5FC3\u3002\\n\\n\u5728 Vercel \u4E0A\uFF0C\u9019\u4E9B SDK \u904B\u884C\u5728 Node.js \u74B0\u5883\u4E2D\uFF0C\u5E7E\u4E4E\u6C92\u6709\u5927\u5C0F\u9650\u5236\u3002\u4F46\u5728 Cloudflare Edge \u74B0\u5883\u4E0B\uFF0C\u6240\u6709\u9019\u4E9B\u90FD\u5FC5\u9808\u585E\u9032\u90A3\u500B\u5C0F\u5C0F\u7684 Worker \u8173\u672C\u88E1\u3002\\n\\n### 2. \u74B0\u5883\u9069\u61C9\u4E0D\u826F (Node.js vs Edge Runtime)\\nNext.js \u8A31\u591A\u65B9\u4FBF\u7684\u529F\u80FD\uFF08\u5982\u67D0\u4E9B\u7279\u5B9A\u6A21\u7D44\u7684\u4F3A\u670D\u5668\u7AEF\u6E32\u67D3\uFF09\u4F9D\u8CF4\u65BC\u5B8C\u6574\u7684 Node.js API\uFF0C\u800C Cloudflare \u7684 Edge Runtime \u5247\u662F\u57FA\u65BC V8 \u7684\u53D7\u9650\u74B0\u5883\u3002\u96D6\u7136 `open-next` \u5DF2\u7D93\u505A\u4E86\u5F88\u591A\u52AA\u529B\uFF0C\u4F46\u8981\u8B93\u6574\u500B App \u5B8C\u7F8E\u9069\u61C9\uFF0C\u9700\u8981\u5927\u91CF\u7684\u91CD\u69CB\u3002\\n\\n## \u6211\u5011\u5617\u8A66\u904E\u7684\u89E3\u6C7A\u65B9\u6848\uFF08\u90A3\u4E9B\u6211\u5011\u8D70\u904E\u7684\u5F4E\u8DEF\uFF09\\n\\n\u96D6\u7136\u7D50\u679C\u662F\u5931\u6557\uFF0C\u4F46\u6211\u5011\u5617\u8A66\u4E86\u6240\u6709\u80FD\u60F3\u5230\u7684\u512A\u5316\u624B\u6BB5\uFF1A\\n\\n1. **\u52D5\u614B\u5C0E\u5165 (Dynamic Imports)**\uFF1A\\n   \u6211\u5011\u5617\u8A66\u5C07\u91CD\u578B\u7684\u7D44\u4EF6\uFF08\u5982\u8A9E\u6CD5\u9AD8\u4EAE\u7684\u7DE8\u8F2F\u5668\uFF09\u6539\u70BA `next/dynamic` \u50C5\u5728\u5BA2\u6236\u7AEF\u8F09\u5165\u3002\u9019\u78BA\u5BE6\u6E1B\u5C0F\u4E86 Server-side \u7684\u58D3\u529B\uFF0C\u4F46\u5C0D\u65BC\u67D0\u4E9B\u5F37\u4F9D\u8CF4\u670D\u52D9\u7AEF\u908F\u8F2F\u7684\u9801\u9762\uFF0C\u512A\u5316\u7A7A\u9593\u4F9D\u7136\u6709\u9650\u3002\\n   \\n2. **SDK \u812B\u6C34 (SDK Stripping)**\uFF1A\\n   \u6211\u5011\u5617\u8A66\u79FB\u9664\u67D0\u4E9B\u975E\u6838\u5FC3\u7684\u91CD\u578B SDK\uFF0C\u6539\u7528\u66F4\u8F15\u91CF\uFF08\u4F46\u529F\u80FD\u8F03\u5C11\uFF09\u7684\u66FF\u4EE3\u54C1\u3002\u4F46\u5C0D\u65BC\u8FFD\u6C42\u300C\u65D7\u8266\u9AD4\u9A57\u300D\u7684\u6211\u5011\u4F86\u8AAA\uFF0C\u9019\u7A2E\u6B0A\u8861\uFF08Trade-off\uFF09\u964D\u4F4E\u4E86\u7522\u54C1\u7684\u8CEA\u611F\u3002\\n\\n3. **OpenNext \u7CBE\u78BA\u914D\u7F6E**\uFF1A\\n   \u8ABF\u6574 `open-next.config` \u4F86\u6392\u9664\u67D0\u4E9B\u4E0D\u5FC5\u8981\u7684 chunks\uFF0C\u4F46 Next.js App Router \u7684\u69CB\u5EFA\u908F\u8F2F\u6709\u6642\u50CF\u500B\u9ED1\u76D2\u5B50\uFF0C\u96E3\u4EE5\u7CBE\u78BA\u62C6\u5206\u3002\\n\\n4. **\u8207\u300C\u770B\u4E0D\u898B\u300D\u7684\u7D30\u7BC0\u5C0D\u6297**\uFF1A\\n   \u6211\u5011\u5728\u74B0\u5883\u8B8A\u6578\uFF08Secrets\uFF09\u7684\u9077\u79FB\u548C **\u5716\u7247\u512A\u5316 (next/image)** \u7684\u914D\u7F6E\u4E0A\u4E5F\u8017\u8CBB\u4E86\u5927\u91CF\u5FC3\u529B\u3002\u5728 Vercel \u9EDE\u9EDE\u4ECB\u9762\u5C31\u80FD\u641E\u5B9A\u7684\u4E8B\uFF0C\u5728 Cloudflare \u9700\u8981\u900F\u904E `wrangler.toml` \u91CD\u65B0\u4F48\u7F72\uFF0C\u751A\u81F3\u8981\u984D\u5916\u5EFA\u7ACB R2 \u5132\u5B58\u6876\u4F86\u652F\u6490\u5716\u7247\u8655\u7406\u3002\\n\\n## \u7D66\u4E0B\u4E00\u500B\u6311\u6230\u8005\u7684 3 \u500B\u5EFA\u8B70\\n\\n\u5982\u679C\u4F60\u4E5F\u6B63\u6253\u7B97\u5C07 Next.js \u61C9\u7528\u90E8\u7F72\u5230 Cloudflare\uFF0C\u8ACB\u52D9\u5FC5\u5148\u78BA\u8A8D\u4EE5\u4E0B\u4E8B\u9805\uFF1A\\n\\n1. **\u6A21\u7D44\u5316\u4F60\u7684\u4F9D\u8CF4**\uFF1A\u5728\u5F15\u5165\u4EFB\u4F55\u5EAB\uFF08Library\uFF09\u4E4B\u524D\uFF0C\u5148\u53BB [BundlePhobia](https://bundlephobia.com/) \u770B\u770B\u5B83\u7684\u9AD4\u7A4D\u3002\\n2. **\u512A\u5148\u8003\u616E Edge-first**\uFF1A\u5F9E\u958B\u767C\u7B2C\u4E00\u5929\u8D77\u5C31\u4EE5 Edge Runtime \u70BA\u57FA\u6E96\u3002\u5982\u679C\u4F60\u662F\u5230\u4E86\u958B\u767C\u4E2D\u5F8C\u671F\u624D\u6C7A\u5B9A\u5207\u63DB\u74B0\u5883\uFF0C\u90A3\u4EE3\u50F9\u53EF\u80FD\u6703\u975E\u5E38\u6C89\u91CD\u3002\\n3. **\u529F\u80FD\u6B0A\u8861**\uFF1A\u5982\u679C\u4F60\u7684\u61C9\u7528\u9700\u8981\u5927\u91CF\u91CD\u578B\u7684 SSR \u6E32\u67D3\u6216\u4F9D\u8CF4\u50B3\u7D71 Node.js \u5EAB\uFF0C\u90A3\u9EBC Vercel \u6216 Netlify \u6216\u8A31\u624D\u662F\u4F60\u66F4\u6EAB\u6696\u7684\u5BB6\u3002\\n\\n## \u7D50\u8A9E\uFF1A\u5931\u6557\u662F\u53E6\u4E00\u7A2E\u5F62\u5F0F\u7684\u7D2F\u7A4D\\n\\n\u96D6\u7136\u9019\u6B21\u90E8\u7F72\u5931\u6557\u4E86\uFF0C\u4F46\u6211\u5011\u5C0D\u65BC LiwenBlog CMS \u7684\u6027\u80FD\u908A\u754C\u6709\u4E86\u66F4\u6DF1\u523B\u7684\u8A8D\u8B58\u3002\u6709\u4E9B\u7F8E\u662F\u9700\u8981\u7A7A\u9593\u652F\u6490\u7684\uFF0C\u800C Cloudflare \u7684\u908A\u7DE3\u8A08\u7B97\u76EE\u524D\u66F4\u50CF\u662F\u4E00\u500B\u300C\u7CBE\u800C\u5C0F\u300D\u7684\u85DD\u8853\u9928\uFF0C\u4E0D\u9069\u5408\u585E\u9032\u6240\u6709\u7684\u6771\u897F\u3002\\n\\n\u6211\u5011\u56DE\u5230\u4E86\u719F\u6089\u7684\u74B0\u5883\uFF0C\u7E7C\u7E8C\u6253\u78E8\u6211\u5011\u7684\u7522\u54C1\u3002\u4E0B\u6B21\u518D\u6311\u6230\u6642\uFF0C\u6211\u5011\u6703\u5E36\u8457\u66F4\u7CBE\u7C21\u3001\u66F4\u5177\u9069\u61C9\u6027\u7684\u4EE3\u78BC\u518D\u6B21\u51FA\u767C\u3002"},{"id":"imposter-syndrome","metadata":{"permalink":"/blog/imposter-syndrome","source":"@site/blog/2026-04-21-imposter-syndrome.md","title":"\u5192\u540D\u9802\u66FF\u75C7\u5019\u7FA4 (Imposter Syndrome) \u6DF1\u5EA6\u89E3\u6790","description":"\u4E92\u52D5\u7DB2\u7AD9","date":"2026-04-21T06:46:36.190Z","tags":[{"inline":true,"label":"\u751F\u6D3B","permalink":"/blog/tags/\u751F\u6D3B"}],"readingTime":3.24,"hasTruncateMarker":false,"authors":[{"name":"Liwen","title":"Digital Architect / Full Stack Developer","url":"https://github.com/liwenchiou","imageURL":"https://github.com/liwenchiou.png","key":"liwen","page":null}],"frontMatter":{"slug":"imposter-syndrome","title":"\u5192\u540D\u9802\u66FF\u75C7\u5019\u7FA4 (Imposter Syndrome) \u6DF1\u5EA6\u89E3\u6790","date":"2026-04-21T06:46:36.190Z","authors":["liwen"],"tags":["\u751F\u6D3B"]},"unlisted":false,"prevItem":{"title":"\u96F2\u7AEF\u908A\u7DE3\u7684\u6298\u7FFC\uFF1ANext.js \u90E8\u7F72\u5230 Cloudflare Pages \u7684 48 \u5C0F\u6642\u596E\u9B25\u5BE6\u9304","permalink":"/blog/\u96F2\u7AEF\u908A\u7DE3\u7684\u6298\u7FFCnextjs-\u90E8\u7F72\u5230-cloudflare-pages-\u7684-48-\u5C0F\u6642\u596E\u9B25\u5BE6\u9304"},"nextItem":{"title":"\u5DE5\u7A0B\u5E2B\u8A55\u50F9\u5FC3\u7406\u5B78\uFF1A\u6DF1\u5EA6\u5B78\u7FD2\u7B46\u8A18","permalink":"/blog/engineer-evaluation-psychology"}},"content":"[\u4E92\u52D5\u7DB2\u7AD9](https://gemini.google.com/share/419d34c2d3f6)\\n\\n## \u4E00\u3001 \u5B9A\u7FA9\uFF1A\u4EC0\u9EBC\u662F\u5192\u540D\u9802\u66FF\u75C7\u5019\u7FA4\uFF1F\\n\\n\u5192\u540D\u9802\u66FF\u75C7\u5019\u7FA4\u6700\u65E9\u7531\u5FC3\u7406\u5B78\u5BB6 **Pauline Clance** \u8207 **Suzanne Imes** \u65BC 1978 \u5E74\u63D0\u51FA\u3002\u5B83\u4E26\u975E\u4E00\u7A2E\u7CBE\u795E\u75BE\u75C5\uFF0C\u800C\u662F\u4E00\u7A2E**\u5FC3\u7406\u73FE\u8C61**\u3002\\n\\n*   **\u6838\u5FC3\u7279\u5FB5\uFF1A** \u500B\u9AD4\u7121\u6CD5\u5C07\u81EA\u5DF1\u7684\u6210\u529F\u6B78\u56E0\u65BC\u80FD\u529B\uFF0C\u5118\u7BA1\u6709\u5916\u90E8\u8B49\u64DA\uFF08\u5982\u8B49\u66F8\u3001\u597D\u8A55\u3001\u6649\u5347\uFF09\uFF0C\u4ECD\u6DF1\u4FE1\u81EA\u5DF1\u662F\u300C\u9A19\u5B50\u300D\uFF0C\u8A8D\u70BA\u6210\u529F\u53EA\u662F\u56E0\u70BA\u904B\u6C23\u3001\u6642\u6A5F\u6216\u8AA4\u5C0E\u4E86\u4ED6\u4EBA\u3002\\n*   **\u5FC3\u7406\u904B\u4F5C\uFF1A** \u9019\u7A2E\u7126\u616E\u901A\u5E38\u4F34\u96A8\u8457\u300C\u5BB3\u6015\u88AB\u62C6\u7A7F\u300D\u7684\u6050\u61FC\uFF0C\u89BA\u5F97\u81EA\u5DF1\u4E0D\u914D\u64C1\u6709\u76EE\u524D\u7684\u5730\u4F4D\u3002\\n\\n---\\n\\n## \u4E8C\u3001 \u5E38\u898B\u7684\u60C5\u6CC1\u8207\u5FB5\u5146\\n\\n\u4F60\u53EF\u4EE5\u5C0D\u7167\u4EE5\u4E0B\u8868\u683C\uFF0C\u6AA2\u8996\u81EA\u5DF1\u662F\u5426\u6709\u76F8\u95DC\u7684\u5FC3\u7406\u611F\u53D7\uFF1A\\n\\n| \u60C5\u6CC1 | \u5167\u5FC3\u7368\u767D\u793A\u4F8B | \u884C\u70BA\u8868\u73FE |\\n| :--- | :--- | :--- |\\n| **\u904E\u5EA6\u6E96\u5099** | \u300C\u6211\u5FC5\u9808\u6BD4\u5225\u4EBA\u591A\u82B1\u4E09\u500D\u6642\u9593\u6E96\u5099\uFF0C\u5426\u5247\u4E00\u5B9A\u6703\u641E\u7838\u3002\u300D | \u5BB9\u6613\u5C0E\u81F4\u7CBE\u75B2\u529B\u7AED (Burnout)\u3002 |\\n| **\u5FFD\u8996\u6210\u5C31** | \u300C\u90A3\u4EFD\u5831\u544A\u6703\u6210\u529F\u53EA\u662F\u56E0\u70BA\u4E3B\u7BA1\u5FC3\u60C5\u597D\uFF0C\u6C92\u4EC0\u9EBC\u4E86\u4E0D\u8D77\u3002\u300D | \u5C07\u6210\u529F\u904E\u5EA6\u6B78\u56E0\u65BC\u904B\u6C23\u6216\u4ED6\u4EBA\u56E0\u7D20\u3002 |\\n| **\u5BB3\u6015\u6311\u6230** | \u300C\u5982\u679C\u6211\u63A5\u4E0B\u9019\u500B\u65B0\u5C08\u6848\uFF0C\u5927\u5BB6\u5C31\u6703\u767C\u73FE\u6211\u5176\u5BE6\u4EC0\u9EBC\u90FD\u4E0D\u61C2\u3002\u300D | \u70BA\u4E86\u907F\u514D\u66DD\u9732\u300C\u7121\u80FD\u300D\u800C\u9003\u907F\u6649\u5347\u6A5F\u6703\u3002 |\\n| **\u793E\u4EA4\u9000\u7E2E** | \u5728\u53B2\u5BB3\u7684\u4EBA\u8EAB\u908A\u4E0D\u6562\u767C\u8A00\uFF0C\u64D4\u5FC3\u8AAA\u932F\u8A71\u6703\u986F\u9732\u7121\u77E5\u3002 | \u96B1\u85CF\u771F\u5BE6\u89C0\u9EDE\uFF0C\u50C5\u63A1\u53D6\u5B89\u5168\u7684\u56DE\u61C9\u3002 |\\n| **\u5B8C\u7F8E\u4E3B\u7FA9** | \u300C\u53EA\u8981\u6709\u4E00\u9EDE\u5C0F\u932F\u8AA4\uFF0C\u5C31\u89BA\u5F97\u81EA\u5DF1\u4E4B\u524D\u7684\u52AA\u529B\u5168\u90FD\u767D\u8CBB\u4E86\u3002\u300D | \u5C0D\u81EA\u6211\u8A55\u50F9\u6975\u7AEF\uFF0C\u96E3\u4EE5\u5BB9\u5FCD\u5408\u7406\u7684\u932F\u8AA4\u3002 |\\n\\n---\\n\\n## \u4E09\u3001 \u9032\u968E\u88DC\u5145\uFF1A\u4E94\u7A2E\u5192\u540D\u9802\u66FF\u8005\u985E\u578B (The 5 Types)\\n\\n\u6839\u64DA Valerie Young \u7684\u7814\u7A76\uFF0C\u5192\u540D\u9802\u66FF\u75C7\u5019\u7FA4\u53EF\u4EE5\u7D30\u5206\u70BA\u4E94\u7A2E\u5178\u578B\uFF0C\u4E86\u89E3\u81EA\u5DF1\u5C6C\u65BC\u54EA\u4E00\u985E\u6709\u52A9\u65BC\u66F4\u7CBE\u6E96\u5730\u8ABF\u6574\u5FC3\u614B\uFF1A\\n\\n1.  **\u5B8C\u7F8E\u4E3B\u7FA9\u8005 (The Perfectionist)\uFF1A** \u8A2D\u5B9A\u904E\u9AD8\u76EE\u6A19\uFF0C\u5373\u4FBF\u9054\u6210 99% \u4ECD\u6703\u70BA\u4E86 1% \u7684\u7455\u75B5\u611F\u5230\u5931\u6557\u3002\\n2.  **\u8D85\u4EBA (The Superhuman)\uFF1A** \u8A66\u5716\u5728\u5DE5\u4F5C\u3001\u5BB6\u5EAD\u3001\u793E\u4EA4\u7B49\u6240\u6709\u9818\u57DF\u90FD\u9054\u5230\u9802\u5C16\uFF0C\u4EE5\u6B64\u63A9\u98FE\u5167\u5FC3\u7684\u4E0D\u5B89\u3002\\n3.  **\u5929\u751F\u5929\u624D (The Natural Genius)\uFF1A** \u7FD2\u6163\u65BC\u8FC5\u901F\u638C\u63E1\u65B0\u4E8B\u7269\uFF0C\u82E5\u9047\u5230\u9700\u8981\u52AA\u529B\u82E6\u7DF4\u624D\u80FD\u5B78\u6703\u7684\u4E8B\uFF0C\u6703\u89BA\u5F97\u81EA\u5DF1\u300C\u6C92\u5929\u8CE6\u3001\u662F\u9A19\u5B50\u300D\u3002\\n4.  **\u7368\u884C\u4FE0 (The Soloist)\uFF1A** \u8A8D\u70BA\u5FC5\u9808\u7368\u7ACB\u5B8C\u6210\u6240\u6709\u4E8B\uFF0C\u8ACB\u6C42\u5E6B\u52A9\u5728\u4ED6\u5011\u773C\u4E2D\u7B49\u540C\u65BC\u300C\u7121\u80FD\u300D\u3002\\n5.  **\u5C08\u5BB6 (The Expert)\uFF1A** \u6C38\u9060\u89BA\u5F97\u81EA\u5DF1\u61C2\u7684\u4E0D\u5920\u591A\uFF0C\u5373\u4FBF\u5DF2\u975E\u5E38\u6709\u7D93\u9A57\uFF0C\u4ECD\u6703\u4E0D\u65B7\u760B\u72C2\u9032\u4FEE\u4EE5\u6C42\u5B89\u5168\u611F\u3002\\n\\n---\\n\\n## \u56DB\u3001 \u5BE6\u7528\u7684\u89E3\u6C7A\u65B9\u5F0F\\n\\n\u514B\u670D\u6B64\u75C7\u5019\u7FA4\u4E26\u975E\u8981\u300C\u6D88\u9664\u300D\u611F\u89BA\uFF0C\u800C\u662F\u5B78\u7FD2\u8207\u4E4B\u5171\u8655\uFF0C\u4E26\u6E1B\u5C11\u5B83\u5C0D\u884C\u52D5\u7684\u963B\u7919\u3002\\n\\n### 1. \u5340\u5206\u300C\u611F\u89BA\u300D\u8207\u300C\u4E8B\u5BE6\u300D\\n\u9019\u662F\u6700\u91CD\u8981\u7684\u7B2C\u4E00\u6B65\u3002\\n*   **\u611F\u89BA\uFF1A** \u300C\u6211\u89BA\u5F97\u81EA\u5DF1\u5F88\u5F31\uFF0C\u5927\u5BB6\u90FD\u5728\u7B11\u6211\u3002\u300D\\n*   **\u4E8B\u5BE6\uFF1A** \u300C\u6211\u6E96\u6642\u63D0\u4EA4\u4E86\u5C08\u6848\uFF0C\u4E14\u76EE\u524D\u6C92\u6709\u6536\u5230\u4EFB\u4F55\u8CA0\u9762\u53CD\u994B\u3002\u300D\\n*   **\u884C\u52D5\uFF1A** \u7576\u7126\u616E\u4F86\u8972\uFF0C\u8A66\u8457\u5BEB\u4E0B\u8CA0\u9762\u60C5\u7DD2\uFF0C\u4E26\u5728\u65C1\u908A\u5217\u51FA\u5BA2\u89C0\u6578\u64DA\u4F86\u53CD\u99C1\u3002\\n\\n### 2. \u5EFA\u7ACB\u300C\u6210\u5C31\u7D00\u9304\u672C\u300D (The Brag Document)\\n\u4EBA\u7684\u5927\u8166\u6709\u300C\u8CA0\u9762\u504F\u5411\u300D\uFF0C\u5BB9\u6613\u5FD8\u8A18\u6210\u529F\u3002\\n*   **\u8A18\u9304\u5167\u5BB9\uFF1A** \u89E3\u6C7A\u904E\u7684\u96E3\u984C\u3001\u5B78\u6703\u7684\u65B0\u6280\u80FD\u3001\u7372\u5F97\u7684\u8B9A\u8CDE\u3002\\n*   **\u4F5C\u7528\uFF1A** \u7576\u4F60\u61F7\u7591\u81EA\u5DF1\u6642\uFF0C\u7FFB\u958B\u7D00\u9304\uFF0C\u8B93\u904E\u53BB\u7684\u6210\u5C31\u6210\u70BA\u73FE\u5728\u7684\u5F8C\u76FE\u3002\\n\\n### 3. \u8207\u4ED6\u4EBA\u5206\u4EAB\u611F\u53D7\\n\u5192\u540D\u9802\u66FF\u75C7\u5019\u7FA4\u5728\u300C\u6C88\u9ED8\u300D\u4E2D\u9577\u5F97\u6700\u5FEB\u3002\\n*   **\u7834\u9664\u795E\u8A71\uFF1A** \u7576\u4F60\u767C\u73FE\u8EAB\u908A\u7684\u300C\u5927\u795E\u300D\u4E5F\u6703\u611F\u5230\u7126\u616E\u6642\uFF0C\u58D3\u529B\u6703\u5927\u5E45\u6E1B\u8F15\u3002\\n*   **\u5C0B\u627E\u5C0E\u5E2B\uFF1A** \u8207\u4FE1\u4EFB\u7684 Mentor \u5206\u4EAB\uFF0C\u5F9E\u5BA2\u89C0\u7B2C\u4E09\u8005\u7684\u8996\u89D2\u91CD\u65B0\u8A55\u4F30\u4F60\u7684\u50F9\u503C\u3002\\n\\n### 4. \u91CD\u65B0\u5B9A\u7FA9\u5931\u6557\uFF1A\u64C1\u62B1\u300C\u6210\u9577\u578B\u601D\u7DAD\u300D\\n*   \u5C07\u300C\u6211\u4E0D\u6703\u300D\u6539\u70BA **\u300C\u6211\u9084\u6C92\u5B78\u6703\u300D**\u3002\\n*   **\u6838\u5FC3\u50F9\u503C\uFF1A** \u5C08\u696D\u4EBA\u58EB\u7684\u50F9\u503C\u4E0D\u5728\u65BC\u7121\u6240\u4E0D\u77E5\uFF0C\u800C\u5728\u65BC**\u5177\u5099\u627E\u5230\u7B54\u6848\u7684\u80FD\u529B**\u3002\\n\\n### 5. \u6AA2\u8996\u74B0\u5883\u56E0\u7D20 (\u88DC\u5145)\\n\u6709\u6642\u9019\u7A2E\u611F\u89BA\u6E90\u65BC\u300C\u74B0\u5883\u300D\u3002\u82E5\u8EAB\u8655\u7AF6\u722D\u904E\u6FC0\u70C8\u6216\u7F3A\u4E4F\u591A\u5143\u5305\u5BB9\u6027\u7684\u8077\u5834\uFF08\u5982\u5C11\u6578\u65CF\u88D4\u3001\u5973\u6027\u5728\u50B3\u7D71\u7537\u6027\u4E3B\u5C0E\u884C\u696D\uFF09\uFF0C\u9019\u7A2E\u5FC3\u7406\u611F\u6703\u88AB\u653E\u5927\u3002\u7406\u89E3\u9019\u4E26\u975E\u55AE\u7D14\u500B\u4EBA\u554F\u984C\uFF0C\u6709\u52A9\u65BC\u7DE9\u89E3\u81EA\u6211\u6279\u5224\u3002\\n\\n---\\n\\n## \u4F86\u6E90\u8207\u53C3\u8003\u8CC7\u6599\\n\\n*   **Clance, P. R., & Imes, S. A. (1978):** *The imposter phenomenon in high achieving women: Dynamics and therapeutic intervention.*\\n*   **Valerie Young (2011):** *The Secret Thoughts of Successful Women.*\\n*   **Harvard Business Review:** [Stop Telling Women They Have Imposter Syndrome](https://hbr.org)"},{"id":"engineer-evaluation-psychology","metadata":{"permalink":"/blog/engineer-evaluation-psychology","source":"@site/blog/2026-04-21-engineer-evaluation-psychology.md","title":"\u5DE5\u7A0B\u5E2B\u8A55\u50F9\u5FC3\u7406\u5B78\uFF1A\u6DF1\u5EA6\u5B78\u7FD2\u7B46\u8A18","description":"\u4E92\u52D5\u7DB2\u7AD9//gemini.google.com/share/6a9569c51762","date":"2026-04-21T06:46:35.933Z","tags":[{"inline":true,"label":"\u751F\u6D3B","permalink":"/blog/tags/\u751F\u6D3B"}],"readingTime":2.97,"hasTruncateMarker":false,"authors":[{"name":"Liwen","title":"Digital Architect / Full Stack Developer","url":"https://github.com/liwenchiou","imageURL":"https://github.com/liwenchiou.png","key":"liwen","page":null}],"frontMatter":{"slug":"engineer-evaluation-psychology","title":"\u5DE5\u7A0B\u5E2B\u8A55\u50F9\u5FC3\u7406\u5B78\uFF1A\u6DF1\u5EA6\u5B78\u7FD2\u7B46\u8A18","date":"2026-04-21T06:46:35.933Z","authors":["liwen"],"tags":["\u751F\u6D3B"]},"unlisted":false,"prevItem":{"title":"\u5192\u540D\u9802\u66FF\u75C7\u5019\u7FA4 (Imposter Syndrome) \u6DF1\u5EA6\u89E3\u6790","permalink":"/blog/imposter-syndrome"},"nextItem":{"title":"\u8EAB\u70BA\u5168\u516C\u53F8\u7684\u907F\u98A8\u6E2F\uFF1AMIS \u7684\u7121\u5948\u65E5\u5E38\u8207\u908A\u754C\u611F","permalink":"/blog/mis-daily-rant"}},"content":"\u4E92\u52D5\u7DB2\u7AD9: [https://gemini.google.com/share/6a9569c51762](https://gemini.google.com/share/6a9569c51762)\\n\\n\u9019\u4EFD\u7B46\u8A18\u6574\u7406\u4E86\u5DE5\u7A0B\u5E2B\u5728\u8077\u5834\u4E2D\u9762\u5C0D\u300C\u8A55\u50F9\u300D\u6642\u7684\u5FC3\u7406\u6A5F\u5236\u3001\u5E38\u898B\u884C\u70BA\u6A21\u5F0F\uFF0C\u4EE5\u53CA\u5982\u4F55\u5EFA\u7ACB\u5065\u5EB7\u7684\u81EA\u6211\u8A8D\u540C\u9AD4\u7CFB\u3002\\n\\n---\\n\\n## \u4E00\u3001\u6838\u5FC3\u554F\u984C\uFF1A\u70BA\u4EC0\u9EBC\u6211\u5011\u5982\u6B64\u5728\u610F\u8A55\u50F9\uFF1F\\n\\n\u5DE5\u7A0B\u5E2B\u7684\u5DE5\u4F5C\u7522\u51FA\uFF08\u4EE3\u78BC\u3001\u67B6\u69CB\uFF09\u9AD8\u5EA6\u62BD\u8C61\u4E14\u5177\u5099\u5275\u9020\u6027\u3002\u7576\u7522\u51FA\u53D7\u5230\u6279\u8A55\u6642\uFF0C\u5927\u8166\u5F80\u5F80\u7121\u6CD5\u5340\u5206\u300C\u5C0D\u5DE5\u4F5C\u7684\u5EFA\u8B70\u300D\u8207\u300C\u5C0D\u500B\u4EBA\u7684\u5426\u5B9A\u300D\u3002\\n\\n### \u5FC3\u7406\u5B78\u4E09\u5927\u6839\u6E90\\n\\n- **\u751F\u5B58\u672C\u80FD\uFF08Survival Instinct\uFF09**  \\n  \u5728\u6F14\u5316\u904E\u7A0B\u4E2D\uFF0C\u88AB\u90E8\u843D\u6392\u65A5\u610F\u5473\u8457\u6B7B\u4EA1\u3002\u5927\u8166\u908A\u7DE3\u7CFB\u7D71\u6703\u5C07\u300C\u8CA0\u9762\u8A55\u50F9\u300D\u8996\u70BA\u7269\u7406\u5A01\u8105\uFF0C\u89F8\u767C\u76AE\u8CEA\u9187\u5206\u6CCC\uFF0C\u5C0E\u81F4\u5FC3\u8DF3\u52A0\u901F\u8207\u7126\u616E\u3002\\n\\n- **\u93E1\u50CF\u81EA\u6211\uFF08Looking-glass Self\uFF09**  \\n  \u67E5\u723E\u65AF\xb7\u5EAB\u5229\uFF08Charles Cooley\uFF09\u63D0\u51FA\u3002\u6211\u5011\u5C0D\u81EA\u5DF1\u7684\u5B9A\u7FA9\uFF0C\u5176\u5BE6\u662F\u6211\u5011\u89C0\u5BDF\u5230\u300C\u5225\u4EBA\u5982\u4F55\u770B\u5F85\u6211\u300D\u7684\u6295\u5F71\u3002\u8A55\u50F9\u6210\u4E86\u6211\u5011\u78BA\u8A8D\u81EA\u8EAB\u80FD\u529B\u7684\u5EA7\u6A19\u3002\\n\\n- **\u793E\u6703\u6BD4\u8F03\u7406\u8AD6\uFF08Social Comparison Theory\uFF09**  \\n  \u5229\u6602\xb7\u8CBB\u65AF\u5EF7\u683C\uFF08Leon Festinger\uFF09\u63D0\u51FA\u3002\u5728\u7F3A\u4E4F\u7D55\u5C0D\u6A19\u6E96\u6642\uFF0C\u4EBA\u985E\u50BE\u5411\u900F\u904E\u8207\u540C\u5115\u6BD4\u8F03\uFF08\u5982\u8077\u7D1A\u3001\u85AA\u8CC7\uFF09\u4F86\u5B9A\u7FA9\u6210\u529F\u3002\\n\\n---\\n\\n## \u4E8C\u3001\u5DE5\u7A0B\u5E2B\u65E5\u5E38\u751F\u52D5\u6848\u4F8B\u5206\u6790\\n\\n\u900F\u904E\u5177\u9AD4\u5834\u666F\uFF0C\u8B58\u5225\u9019\u4E9B\u5FC3\u7406\u6A5F\u5236\u5982\u4F55\u5F71\u97FF\u958B\u767C\u8005\u7684\u884C\u70BA\uFF1A\\n\\n| \u6848\u4F8B\u89D2\u8272 | \u6838\u5FC3\u60C5\u5883 | \u5FC3\u7406\u5206\u6790 |\\n|----------|----------|----------|\\n| **\u8001\u738B\u7684 PR \u7126\u616E** | \u6536\u5230 Request Changes \u6216\u300C\u908F\u8F2F\u7B28\u300D\u7684\u8A55\u8AD6 | \u5916\u5728\u8A08\u5206\u5361\u4E3B\u5C0E\u3002\u5C07\u4EE3\u78BC\u54C1\u8CEA\u8207\u667A\u529B\u639B\u9264\uFF0C\u5C0E\u81F4\u9632\u79A6\u5FC3\u614B |\\n| **\u5C0F\u7F8E\u7684\u6280\u8853\u50B5\u6050\u61FC** | \u64D4\u5FC3\u6539\u58DE\u4EE3\u78BC\u5F71\u97FF\u300C\u7A69\u91CD\u300D\u5F62\u8C61\uFF0C\u6545\u4E0D\u6562\u91CD\u69CB | \u751F\u5B58\u672C\u80FD\u8207\u793E\u4EA4\u5B89\u5168\u6027\u3002\u70BA\u4E86\u7DAD\u6301\u96F6\u5931\u8AA4\u8A55\u50F9\u800C\u72A7\u7272\u6280\u8853\u50F9\u503C |\\n| **\u963F\u5F37\u7684\u6280\u8853\u7126\u616E** | \u76F2\u76EE\u5F15\u5165\u5927\u5EE0\u65B0\u6846\u67B6\uFF0C\u8FFD\u6C42\u6280\u8853\u6D41\u884C | \u793E\u6703\u6BD4\u8F03\u7406\u8AD6\u3002\u5728\u8DDF\u300C\u793E\u7FA4\u5E7B\u89BA\u300D\u6BD4\u8F03\uFF0C\u8A66\u5716\u900F\u904E\u5DE5\u5177\u63DB\u53D6\u8A8D\u53EF |\\n| **\u5927\u529B\u7684\u6551\u706B\u82F1\u96C4** | \u4EAB\u53D7\u534A\u591C\u7B2C\u4E00\u500B\u4FEE Bug \u7684\u300C\u88AB\u9700\u8981\u611F\u300D | \u6548\u7528\u8A8D\u53EF\u6C89\u8FF7\u3002\u6210\u529F\u5EFA\u7ACB\u5728\u88AB\u9700\u8981\u7684\u983B\u7387\uFF0C\u800C\u975E\u9577\u671F\u7522\u51FA\u5F71\u97FF\u529B |\\n| **\u66C9\u82AC\u7684\u6587\u6A94\u5B8C\u7F8E\u4E3B\u7FA9** | \u82B1\u8CBB\u904E\u591A\u6642\u9593\u6F64\u98FE\u6587\u6A94\uFF0C\u64D4\u5FC3\u4E00\u500B\u932F\u5B57\u6BC0\u5C08\u696D\u611F | \u5B8C\u7F8E\u4E3B\u7FA9\u4E0B\u7684\u8A55\u50F9\u6B0A\u653E\u5927\u3002\u5728\u908A\u969B\u6548\u76CA\u6975\u4F4E\u7684\u5DE5\u4F5C\u4E0A\u6D88\u8017\u904E\u5EA6 |\\n\\n---\\n\\n## \u4E09\u3001\u5BE6\u8E10\u89E3\u6C7A\u65B9\u6848\uFF1A\u596A\u56DE\u8A55\u50F9\u4E3B\u5C0E\u6B0A\\n\\n### 1. \u5EFA\u7ACB\u300C\u5167\u5728\u8A08\u5206\u5361\u300D\uFF08Inner Scorecard\uFF09\\n\u83EF\u502B\xb7\u5DF4\u83F2\u7279\uFF08Warren Buffett\uFF09\u63D0\u51FA\u7684\u6982\u5FF5\u3002\u91CD\u9EDE\u5728\u65BC\u4F60\u662F\u7528\u300C\u81EA\u5DF1\u7684\u6A19\u6E96\u300D\u9084\u662F\u300C\u5225\u529B\u7684\u6A19\u6E96\u300D\u4F86\u8861\u91CF\u6210\u529F\u3002\\n\\n- **\u5167\u5728\u6307\u6A19**\uFF1A\u4ECA\u5929\u7684\u6211\u6BD4\u4E09\u500B\u6708\u524D\u66F4\u9032\u6B65\u55CE\uFF1F\u6211\u89E3\u6C7A\u4E86\u771F\u5BE6\u7684\u554F\u984C\u55CE\uFF1F  \\n- **\u5916\u5728\u6307\u6A19**\uFF1AGitHub Stars\u3001\u4E3B\u7BA1\u7684\u8A55\u5206\u5B57\u6BCD\u3001\u540D\u7247\u4E0A\u7684\u982D\u929C\u3002\\n\\n### 2. \u81EA\u6211\u8207\u4EE3\u78BC\u7684\u89E3\u8026\uFF08Decoupling\uFF09\\n- **\u5FC3\u614B\u91CD\u69CB**\uFF1A\u4EE3\u78BC\u96E2\u958B\u7DE8\u8F2F\u5668\u5F8C\uFF0C\u5B83\u5C31\u662F\u4E00\u500B\u7368\u7ACB\u7684\u908F\u8F2F\u5BE6\u9AD4\u3002  \\n- **\u5B9A\u7FA9**\uFF1A\u88AB Review \u7684\u662F\u300C\u4EE3\u78BC\u7684\u6642\u7A7A\u8907\u96DC\u5EA6\u300D\uFF0C\u800C\u4E0D\u662F\u300C\u4F60\u7684\u4EBA\u683C\u300D\u3002\\n\\n### 3. \u64C1\u62B1\u300C\u51E1\u4EBA\u5316\u5FC3\u614B\u300D\\n- \u627F\u8A8D\u81EA\u5DF1\u4E5F\u6709\u4E0D\u61C2\u7684\u5730\u65B9\uFF0C\u9019\u4E26\u4E0D\u6703\u640D\u5BB3\u8CC7\u6DF1\u5DE5\u7A0B\u5E2B\u7684\u5A01\u4FE1\u3002  \\n- \u4E3B\u52D5\u63D0\u554F\u80FD\u5EFA\u7ACB\u5718\u968A\u7684\u300C\u5FC3\u7406\u5B89\u5168\u6027\u300D\uFF0C\u8B93\u6E9D\u901A\u56DE\u5230\u89E3\u6C7A\u554F\u984C\u7684\u672C\u8CEA\u3002\\n\\n---\\n\\n## \u56DB\u3001\u7E3D\u7D50\u8207\u5EA7\u53F3\u9298\\n\\n> **\u300C\u8A55\u50F9\u662F\u4E00\u9805\u5DE5\u5177\uFF0C\u800C\u4E0D\u61C9\u662F\u4F60\u7684\u4E3B\u4EBA\u3002\u300D**\\n\\n\u7576\u4F60\u5C08\u6CE8\u65BC\u5167\u5728\u6210\u9577\u6642\uFF0C\u5916\u90E8\u7684\u8A8D\u53EF\u6703\u4F5C\u70BA\u300C\u526F\u7522\u54C1\u300D\u81EA\u7136\u96A8\u4E4B\u800C\u4F86\uFF0C\u800C\u4E0D\u518D\u662F\u4F60\u7126\u616E\u7684\u6E90\u982D\u3002\\n\\n---\\n\\n## \u53C3\u8003\u4F86\u6E90\u53CA\u9032\u968E\u95B1\u8B80\\n\\n- **Festinger, L. (1954):** *A theory of social comparison processes.* \uFF08\u793E\u6703\u6BD4\u8F03\u7406\u8AD6\uFF09  \\n- **Cooley, C. H. (1902):** *Human Nature and the Social Order.* \uFF08\u93E1\u50CF\u81EA\u6211\u7406\u8AD6\uFF09  \\n- **Schroeder, A. (2008):** *The Snowball.* \uFF08\u5DF4\u83F2\u7279\u50B3\u8A18\uFF1A\u5167\u5728\u8A08\u5206\u5361\u6982\u5FF5\uFF09  \\n- **Dweck, C. S. (2006):** *Mindset: The New Psychology of Success.* \uFF08\u6210\u9577\u578B\u601D\u7DAD\uFF09  \\n- **Brooks, F. P. (1975):** *The Mythical Man-Month.* \uFF08\u8EDF\u9AD4\u5DE5\u7A0B\u5FC3\u7406\u5354\u4F5C\uFF09"},{"id":"mis-daily-rant","metadata":{"permalink":"/blog/mis-daily-rant","source":"@site/blog/2026-04-21-mis-daily-rant.md","title":"\u8EAB\u70BA\u5168\u516C\u53F8\u7684\u907F\u98A8\u6E2F\uFF1AMIS \u7684\u7121\u5948\u65E5\u5E38\u8207\u908A\u754C\u611F","description":"\u9019\u539F\u672C\u61C9\u8A72\u662F\u500B\u7F8E\u597D\u7684\u88DC\u7720\u65E5\u3002\u56E0\u70BA\u524D\u4E00\u5929\u6C92\u7761\u597D\uFF0C\u7D22\u6027\u8ACB\u4E86\u4E00\u5929\u5047\uFF0C\u6253\u7B97\u597D\u597D\u5145\u96FB\u5F8C\uFF0C\u518D\u4F86\u5C08\u5FC3\u8655\u7406\u6700\u8FD1\u4E00\u76F4\u6C92\u7A7A\u57F7\u884C\u7684\u8CC7\u8A0A\u9700\u6C42\u3002\u6C92\u60F3\u5230\uFF0C\u7F8E\u597D\u7684\u65E9\u6668\u5728\u516B\u9EDE\u591A\u5C31\u88AB\u7121\u60C5\u6253\u65B7\u3002","date":"2026-04-21T06:46:35.682Z","tags":[{"inline":true,"label":"\u8077\u5834","permalink":"/blog/tags/\u8077\u5834"}],"readingTime":2.02,"hasTruncateMarker":false,"authors":[{"name":"Liwen","title":"Digital Architect / Full Stack Developer","url":"https://github.com/liwenchiou","imageURL":"https://github.com/liwenchiou.png","key":"liwen","page":null}],"frontMatter":{"slug":"mis-daily-rant","title":"\u8EAB\u70BA\u5168\u516C\u53F8\u7684\u907F\u98A8\u6E2F\uFF1AMIS \u7684\u7121\u5948\u65E5\u5E38\u8207\u908A\u754C\u611F","date":"2026-04-21T06:46:35.682Z","authors":["liwen"],"tags":["\u8077\u5834"]},"unlisted":false,"prevItem":{"title":"\u5DE5\u7A0B\u5E2B\u8A55\u50F9\u5FC3\u7406\u5B78\uFF1A\u6DF1\u5EA6\u5B78\u7FD2\u7B46\u8A18","permalink":"/blog/engineer-evaluation-psychology"}},"content":"\u9019\u539F\u672C\u61C9\u8A72\u662F\u500B\u7F8E\u597D\u7684\u88DC\u7720\u65E5\u3002\u56E0\u70BA\u524D\u4E00\u5929\u6C92\u7761\u597D\uFF0C\u7D22\u6027\u8ACB\u4E86\u4E00\u5929\u5047\uFF0C\u6253\u7B97\u597D\u597D\u5145\u96FB\u5F8C\uFF0C\u518D\u4F86\u5C08\u5FC3\u8655\u7406\u6700\u8FD1\u4E00\u76F4\u6C92\u7A7A\u57F7\u884C\u7684\u8CC7\u8A0A\u9700\u6C42\u3002\u6C92\u60F3\u5230\uFF0C\u7F8E\u597D\u7684\u65E9\u6668\u5728\u516B\u9EDE\u591A\u5C31\u88AB\u7121\u60C5\u6253\u65B7\u3002\\n\\n## \u5728\u6700\u5F8C\u4E00\u523B\u624D\u6C42\u6551\u7684\u300C\u4E9E\u99AC\u905C\u8CE3\u5834\u300D\u4E8B\u4EF6\\n\\n\u4E00\u5927\u65E9\u88AB\u5435\u9192\uFF0C\u5C45\u7136\u662F\u56E0\u70BA\u884C\u92B7\u90E8\u9580\u4ECA\u5929\u8981\u958B\u8CE3\u5834\uFF0C\u624D\u767C\u73FE\u7576\u521D\u7533\u8ACB\u7684\u4E9E\u99AC\u905C\u5E33\u865F\u9084\u9700\u8981\u518D\u7533\u8ACB Seller \u7684\u76F8\u95DC\u8A8D\u8B49\u3002\u9019\u8B93\u6211\u6EFF\u982D\u554F\u865F\uFF1A\u5E7E\u500B\u6708\u524D\u5E33\u865F\u7533\u8ACB\u5B8C\u4E0D\u5C31\u5DF2\u7D93\u79FB\u4EA4\u4E86\u55CE\uFF1F\u70BA\u4EC0\u9EBC\u73FE\u5728\u9084\u8981\u6211\u4F86\u5E6B\u5FD9\u7533\u8ACB\uFF1F\\n\\n\u5982\u679C\u662F\u6211\u8CA0\u8CAC\u4E00\u500B\u5C08\u6848\uFF0C\u62FF\u5230\u5E33\u865F\u7684\u7B2C\u4E00\u5929\uFF0C\u6211\u4E00\u5B9A\u6703\u5148\u767B\u5165\u9032\u53BB\u9EDE\u9EDE\u770B\uFF0C\u78BA\u8A8D\u80FD\u4E0D\u80FD\u9806\u5229\u958B\u8CE3\u5834\u3001\u719F\u6089\u4E00\u4E0B\u6D41\u7A0B\u3002\u6211\u5BE6\u5728\u7121\u6CD5\u7406\u89E3\uFF0C\u70BA\u4EC0\u9EBC\u7E3D\u662F\u6709\u4EBA\u559C\u6B61\u62D6\u5230\u300C\u6700\u5F8C\u95DC\u982D\u300D\u624D\u5728\u90A3\u908A\u9A5A\u614C\u6C42\u6551\uFF0C\u771F\u7684\u662F\u6703\u8B93\u4EBA\u7406\u667A\u7DDA\u65B7\u88C2\u3002\\n\\n## \u7F3A\u6771\u7F3A\u897F\u7684\u8CC7\u6599\u6574\u7406\\n\\n\u672C\u4F86\u60F3\u8AAA\u76F4\u63A5\u628A\u9019\u4EF6\u4E8B\u653E\u751F\u4E0D\u7406\uFF0C\u8F49\u982D\u6E96\u5099\u4F86\u5C08\u5FC3\u8655\u7406\u6211\u7684\u8CC7\u8A0A\u9700\u6C42\u3002\u7D50\u679C\u4E00\u6253\u958B\u8CC7\u6599\uFF0C\u53C8\u662F\u4E00\u9663\u8840\u58D3\u98C6\u5347\uFF1A\u8CC7\u6599\u7F3A\u6771\u7F3A\u897F\uFF0C\u8A72\u9023\u7D50\u7684\u8CC7\u6599\u5B8C\u5168\u6C92\u6709\u5C0D\u61C9\u8D77\u4F86\u3002\\n\\n\u6211\u5C31\u554F\uFF0C\u9019\u4E0D\u904E\u624D 30 \u5E7E\u7B46\u8CC7\u6599\u800C\u5DF2\uFF01\u64CD\u4F5C\u908F\u8F2F\u4E0D\u5C31\u662F\u9EDE\u500B\u7DE8\u8F2F\u3001\u5728\u4E0B\u62C9\u5F0F\u9078\u55AE\u9078\u597D\u5206\u985E\u3001\u7136\u5F8C\u6309\u4E0B\u5132\u5B58\u55CE\uFF1F\u9019\u56F0\u96E3\u9EDE\u5230\u5E95\u5728\u54EA\u88E1\uFF1F\\n\\n\u7D50\u679C\u5C0D\u65B9\u9084\u8AAA\u8981\u518D\u62C9\u4E00\u500B\u4EBA\u9032\u4F86\u78BA\u8A8D\u3002\u5230\u5E95\u8981\u78BA\u8A8D\u4EC0\u9EBC\uFF1F\u4ECB\u9762\u4E0A\u5168\u90E8\u90FD\u662F\u4E2D\u6587\u5B57\uFF01\u7136\u5F8C\u53C8\u958B\u59CB\u626F\u8AAA\u300C\u6211\u7684\u4EE3\u865F\u8DDF\u4ED6\u5011\u7FD2\u6163\u7684\u4E0D\u4E00\u6A23\u300D\u2026\u2026\u963F\u4F60\u9078\u4E0B\u62C9\u9078\u55AE\u7684\u6642\u5019\u660E\u660E\u770B\u5230\u7684\u662F\u4E2D\u6587\u554A\uFF0C\u9019\u5230\u5E95\u95DC\u4EE3\u865F\u4EC0\u9EBC\u4E8B\uFF1F\\n\\n## MIS \u4E0D\u662F\u6C92\u6709\u5E95\u7DDA\u7684\u300C\u907F\u98A8\u6E2F\u300D\\n\\n\u7E3D\u4E4B\uFF0C\u4ECA\u5929\u5C31\u662F\u5145\u65A5\u8457\u9019\u4E9B\u4EE4\u4EBA\u7121\u8A9E\u7684\u9CE5\u4E8B\u3002\\n\\n\u8D8A\u60F3\u8D8A\u89BA\u5F97\uFF0C\u5F85\u5728\u9019\u88E1\uFF0C\u6211\u597D\u50CF\u4E0D\u77E5\u4E0D\u89BA\u8B8A\u6210\u4E86\u5168\u516C\u53F8\u7684\u300C\u907F\u98A8\u6E2F\u300D\u3002\u5F77\u5F7F\u53EA\u8981\u8DDF\u300C\u96FB\u8166\u3001\u7CFB\u7D71\u3001\u5E33\u865F\u300D\u6CBE\u4E0A\u4E00\u9EDE\u908A\uFF0C\u628A\u6771\u897F\u5F80 MIS \u8EAB\u4E0A\u4E00\u4E1F\uFF0C\u5269\u4E0B\u7684\u4E8B\u60C5\u5C31\u5168\u90E8\u8207\u4ED6\u5011\u7121\u95DC\u4E86\u3002\\n\\n\u9019\u4E0D\u53EA\u662F\u5DE5\u4F5C\u6280\u80FD\u7684\u5DEE\u7570\uFF0C\u66F4\u591A\u7684\u662F\u5C0D\u81EA\u5DF1\u5DE5\u4F5C\u696D\u52D9**\u7F3A\u4E4F\u6240\u6709\u6B0A (Ownership)** \u8207**\u8CAC\u4EFB\u611F**\u7684\u554F\u984C\u3002\u7576\u6BCF\u500B\u4EBA\u90FD\u9810\u671F\u300C\u53CD\u6B63\u51FA\u5305\u4E86\u3001\u4E0D\u6703\u7528\u4E86\uFF0C\u6700\u5F8C MIS \u6703\u5E6B\u5FD9\u64E6\u5C41\u80A1\u300D\uFF0C\u9019\u7A2E\u4F9D\u8CF4\u5FC3\u7406\u5C31\u6703\u7121\u6B62\u76E1\u5730\u8513\u5EF6\u3002\\n\\n\u662F\u6642\u5019\u91CD\u65B0\u5EFA\u7ACB\u5DE5\u4F5C\u4E0A\u7684\u908A\u754C\u611F\u4E86\u3002\u4E0D\u80FD\u518D\u8B93\u300C\u592A\u597D\u8AAA\u8A71\u300D\u8B8A\u6210\u5225\u4EBA\u63A8\u5378\u8CAC\u4EFB\u7684\u7406\u7531\u3002"}]}}')}}]);